quests[28237] = { id = 28237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blight Upon the Land", description = "With the undead outbreak contained, the time has come for Stillwater and his followers to answer for their crimes. Though we averted a tragedy the likes of which has not been seen since the Scourge invaded, we must ensure that such a thing can never happen again. They will all face true death!\n\nCome, {name}! I will have Stillwater's head!", progress = "Do not waste my time, {name}.", completion = "I will deliver this head to the Banshee Queen personally. Of course I will make mention of your part in all of this, {name}.\n\nAs for your reward - take from Stillwater's cache whatever you desire. You earned it.", objectives = "Take the Head of Warden Stillwater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28238] = { id = 28238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Shores", description = "The time has come, {class}. With Stormwind secure, we will take this fight to the enemy. To the Highlands!\n\nThe bulk of our navy has already shipped out, thanks to your work earlier. But Fargo Flintlocke has prepared a seaplane that can make the journey in double-time.\n\nSpeak with Flintlocke down at the harbor and tell him that you are to accompany him to the Highlands. He will be by the water's edge. Safe journeys, {name}.", completion = "A ride to the Highlands, then? I've just the thing!\n\nI'll make room for yeh in me seaplane. I'll have to ditch the cat-food I was packing, yeh know, in case we crash in the mountains and ain't rescued fer weeks.\n\nOn second thought, jes' keep the cat food on yer lap, aye.", objectives = "Speak with Fargo Flintlocke at Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28239] = { id = 28239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Black Tooth Hovel", description = "This isn't really the most... convincing disguise I've seen, but it'll work.  Undercover work is all about swagger, anyhow.  Just act like you're supposed to be there, and you'll be fine.\n\nYour contact inside Black Tooth Hovel will be an orc by the name of Quartermaster Kaoshin.  He does NOT know you're a spy, so try and stay cool.\n\nDo whatever Kaoshin asks you.  Colonel Troteman will be in touch via gnomecorder to give you any special instructions.\n\nGood luck out there, soldier.", completion = "Where have you been, grunt?  You're late!  Give me one reason why I shouldn't kill you on the spot!", objectives = "Speak with Quartermaster Kaoshin at the Black Tooth Hovel in Burning Steppes.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28240] = { id = 28240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapped Out", description = "Listen, {name}.\n\nYou know I live to entertain you, and that I strive to keep you pleasantly occupied and whatnot.\n\nBut it just so happens that I've completely run out of ideas.\n\nThat was it!\n\nUsusally as I'm questing with you I can think of a few things to have you do next, which buys me time to cook up some grand objective, but no more.\n\nI'm tapped out. Completely uninspired. Couldn't muster up another idea to save my life.\n\nOh, wait!I know what we can do!\n\nTalk to me in a week or two...", objectives = "Harrison Jones wants you to talk to him again in a week or two.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28241] = { id = 28241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vision of Twilight", description = "Cho'gall keeps track of his minions through these funny magical balls: \"The Eyes of Twilight.\"\n\nIf I could get me hands on one of those, I bet we could use it to look in on Cho'gall and see what his creeps are up to. Get me one!\n\nSearch the Black Breach, east of here and just north of the river. Find me an Eye of Twilight, and do whatever you gotta do to bring it back here.", completion = "<The Eye sits before you, humming ominously with dark energies.>\n\n<Without warning, the orb rotates, as if to look at you. You sense a malevolent presence, as though the orb is alive.>", objectives = "Locate an Eye of Twilight within the Black Breach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28242] = { id = 28242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Must Sacrifice", description = "<The eye speaks to you, its 'voice' reverberating as if coming from everywhere at once.>\n\nYou seek my sight, {race}? My powers come at a price. These disciples of the Twilight have been honoring me with the blood of Wildhammer dwarves from the nearby ruins, but still I thirst. Perhaps you can do better.\n\nSlay my old masters, and my vision is yours. Honor me with the slaughter of the Shaman of the Black. Blood is blood, after all.", progress = "I have been watching you, {race}.", completion = "<The Eye glimmers darkly, colors swirling about its dusky surface.>\n\nAh, the succulent thrill of life extinguished. Do you feel it, {class}? Do you relish it as I do?\n\nNo, I see not. You fight to protect the lives of others. Pity.", objectives = "Slay 10 Shaman of the Black.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28243] = { id = 28243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes Have It", description = "Very well then, {race}. You have purchased my services in blood. Take me back to the \"Low Shaman\" of Thundermar.\n\nOh yes, I already know where you're taking me. Blundy's meager, ale-soaked abilities are trivial. But you - you fascinate me, {race}. With my sight and your abilities, imagine the havoc we could unleash into this pathetic world together...", progress = "You again? Wot? You bring me somethun'?", completion = "You found one? A gen-u-ine Eye of Twilight? Lemme see.\n\nOh Gods. It's lookin' at me. It's lookin' right back!\n\nI need a drink. Can you face that thing toward the wall or somethin'?", objectives = "Take the Eye of Twilight to Low Shaman Blundy at Thundermar in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28244] = { id = 28244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Spy", description = "I'll be honest, {name}. That thing gives me the willy-willies. But seein' as you went to all the trouble of bringin' it here, I s'pose we ought to put it to use.\n\nYou first.\n\nPeer into the eye and ask it to show you inside Cho'gall's Bastion of Twilight. We'll find out what that fat two-headed bugger is up to, and use it against him.", progress = "Whad'ya see, {class}?", completion = "What did you see, {name}? Cho'gall? Wait - he saw YOU!?\n\nOh aye, that wee sneaky eye! It looks both ways. That cheeky looker! Where's me hammer!?", objectives = "Peer into the Eye of Twilight for Low Shaman Blundy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28245] = { id = 28245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grunt Work", description = "Bah!  You're lucky I'm short-handed today.  Otherwise I'd make you my personal whipping <boy/girl> for the week.\n\nThe officers and high-ranking soldiers need their boots polished.  They've left them out in front of their huts.\n\nI want to see my reflection in those boots, grunt!  Get to work!", progress = "Oh, you're asking for it now, grunt.", completion = "Hmph.  Good work, grunt.", objectives = "Vigorously polish 7 pairs of Blackrock Boots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28246] = { id = 28246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Cuts", description = "<Static> {name}... {name}, can you hear me?  It's Troteman.\n\nListen, we've just received the final bit of intel for your next mission.  There are three marks that we'd like you to take down.  The first is Voodooist Timan, whom you'll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.\n\nYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.", completion = "Not only did you pull off the executions, you made them all look like accidents!\n\nYou were the right {race} for this undercover work.  Good job, soldier.", objectives = "Use the Razor-Sharp Scorpid Barb on Voodooist Timan atop the Pillar of Ash, Worgmistress Othana in the worg pens, and Gorlop when he is near the lava pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28247] = { id = 28247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last of Her Kind", description = "Obsidia is one of the last mature dragons that can continue the black dragonflight bloodline. She must be killed.\n\nIf you succeed in killing her, you should inform Lirastrasza immediately of your victory. She's been fighting a long time to see this done.\n\nThank you for being our fang in these battles. You've proven a powerful ally.", completion = "You killed Obsidia within her own lair? Impressive, {race}. I'm sorry that I could not be there.\n\nYou're true to your word, and you most certainly have the bite to back your bellow. Thank you.", objectives = "Kill Obsidia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28248] = { id = 28248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victors' Point", description = "You've more than proved your intent and your abilities. With Grim Batol cut off and the black dragons routed, the Twilight's Hammer are cornered in their Citadel.\n\nGo to your leaders. You should find them northwest, at Victors' Point. Let them know that when the attack on the Twilight Citadel begins, the red flight shall fill the skies above. You may not be able to atone for all of the sins your allies have committed, but in this one battle, we shall be by your side.\n\nThe Twilight's Hammer will fall.", completion = "You've done well, {name}. We're in the process of preparing the attack now.", objectives = "Speak to Kurdran Wildhammer at Victor's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28249] = { id = 28249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushblow", description = "You've more than proved your intent and your abilities. With Grim Batol cut off and the black dragons routed, the Twilight's Hammer are cornered in their Citadel.\n\nGo to your leaders. You should find them west, at Crushblow. Let them know that when the attack on the Twilight Citadel begins, the red flight shall fill the skies above. You may not be able to atone for all of the sins your allies have committed, but in this one battle, we shall be by your side.\n\nThe Twilight's Hammer will fall.", completion = "You've done well, {name}. We're in the process of preparing the attack now.", objectives = "Speak to Warlord Zaela at Crushblow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28250] = { id = 28250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Little Pluckers", description = "I don't have the most glamorous job in the world.\n\nI do not concern myself with matters of war or the deep mysteries of the halls of Uldum or what have you.\n\nI am in charge of these grounds... and these grounds grow dates.\n\nNow, these little date-plucking mongrels have gotten gutsy enough to stand on each other's shoulders to try and steal my precious fruit.\n\nI will not stand for this.\n\nTake this mallet, crafted by the titans, blessed by the sun-kings and who-knows-what-else and smash the runts!", progress = "Did you do it, {name}?", completion = "You showed those thieving little scoundrels!  Great job.", objectives = "Smash 30 Sand Pygmies with the Tahret Dynasty Mallet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28251] = { id = 28251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Southshore", description = "Before my capture and imprisonment, I was stationed at Southshore. My primary job at the ruins was to take slime samples and make sure that the blight that we released was safely dissipating. Simple and easy if not for the worgen that would continuously harass us.\n\nI need you to head to Southshore and find my apprentice, Serge Hinott. Make sure that he's ok and inform him that I will return once my work here has concluded.\n\nYou'll find the Ruins of Southshore to the southeast, near the coast.", completion = "The worgen situation hasn't gotten any better and Helcular is really creeping me out.", objectives = "Speak to Serge Hinott at the Ruins of Southshore in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28252] = { id = 28252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kodocaller's Horn", description = "Alright, I've got some actual, legitimate, important work for you.  We've got to call the kodos in from the grazing lands to the south.  General Thorg'izog says we'll be moving out into Redridge soon, and I won't be caught with my kodos down.\n\nUse this horn near a kodo.  It will return to the camp when it hears the call.\n\nYou'll want to watch out.  Sometimes the kodos get a little feisty, so you need to knock them around a bit before they listen to you.", objectives = "Use the Horn of the Callers to call 7 Blackrock War Kodos back to camp. If a kodo turns hostile, fight it until it submits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28253] = { id = 28253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Horn For Ourselves", description = "{name}, it's Troteman.  I want you to hold onto that horn.  I'm sure we can improvise and find a way to work it into the plan.\n\nI'm more than a little concerned about what Kaoshin said about attacking Redridge.  We knew another attack was imminent, but our timetables were off by several days.\n\nReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You're not done with your undercover work yet.", progress = "Welcome back, soldier.", completion = "I didn't count on obtaining an item like this.  I will change our plans accordingly.", objectives = "Bring the Horn of the Callers back to Colonel Troteman at Chiselgrip in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28254] = { id = 28254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Needle in a Hellhole", description = "You and I can't take on an army, {name}.  They'll overwhelm us.  That's why we've got to stick to Troteman's plan.\n\nThe next part of the plan is going to require a bit of subtlety... something that I'm not terribly good at.  That's where you come in.\n\nSpeak with Thelaron Direneedle, the tailor here in town.  I've already given him the hides and mud that we've collected.  He's going to need to size you.\n\nThat's right, {name}: you're going undercover.", completion = "You need a disguise?  Well, you came to the right place, honey.\n\nLet me take a look... mm-hmm.  I know exactly what we'll do.", objectives = "Speak with Thelaron Direneedle at Chiselgrip in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28255] = { id = 28255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vhat's Next?", description = "Vhich vay vill zhings turn out? Hmm?\n\nVill I turn on my dark master, whoever zhat might be?\n\nVill I learn to become a more sensitif and compassionate leader? Vill I go so far as to drop my adorable dialect?\n\nOr vill I embrace my aspirations and press forvard at all costs, never satisfied until all of Azerozh is mine?\n\nAnd vhat zhen, hmm?\n\nMaybe it vill all come togezher next veek...\n\n...or maybe zhe veek after zhat...", objectives = "Commander Schnottz just wants a hug...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28256] = { id = 28256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skull of Gul'dan", description = "Illidan set out to find the Skull of Gul'dan. He fought through armies of demons to reach it, slaying them with the power that made him a hated outcast.\n\nSee him in battle, {class}. Witness the one that fought the fiercest against the corruptors of Felwood, and struck at its source.", completion = "Now you are beginning to see...", objectives = "Relive Illidan's battle for the Skull of Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28257] = { id = 28257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Tichondrius", description = "Yes, Illidan took the power of the Skull of Gul'dan for himself.\n\nBut did he flee with it into the night? Did he use it for his own glory? No... his very first action was to use his new power to assault the dreadlord Tichondrius!\n\nWitness his triumph, {class}. Witness how Illidan reclaimed Felwood from the demons... and the thanks he was given.", completion = "Do you see now? For doing what was needed to drive the demons from these lands, my master was banished.\n\nNow these druids pick up the pieces, patting themselves on the back for scrubbing the remaining vestiges of the legion's forces.\n\nBut that is not why I killed them.", objectives = "Relive Illidan's battle with Tichondrius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28258] = { id = 28258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Signilda Hardforge", description = "Signilda Hardforge sent a message for you. She wants you to join her at her at the Training Hall in Stormwind's Old Town as quickly as you can. It sounded important, {name}.", completion = "It's good to see you again, {name}. I wish I could say that I had happy news.", objectives = "Speak to Signilda Hardforge at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28259] = { id = 28259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Evelyn Thorn", description = "I just received a scroll from Evelyn Thorn in Stormwind. She wants you to pay a visit to the Training Hall in Stormwind. She doesn't mention specifics, but I got the impression that it was a matter of some importance.", completion = "I see you received my message. An opportunity has presented itself, {name}, one which will allow us to demonstrate just how important we are to the success of Stormwind and the Alliance.", objectives = "Speak with Evelyn Thorn at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28260] = { id = 28260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Dalgrun Steelpine", description = "Dalgrun Steelpine sends word from Stormwind -- he wants to meet with you right away. He'll be waiting for you in the Training Hall in Stormwind's Old Town district.", completion = "I'll be brief, {name}. Our enemies are gathering and Stormwind needs our help.", objectives = "Speak with Dalgrun Steelpine at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28261] = { id = 28261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deceivers In Our Midst", description = "Now that you've had a lesson in keeping an open mind, perhaps you'd like to learn WHY I killed those druids.\n\nThe answer is simple: They are not druids at all.\n\nDemons still roam the ruins, now hiding in plain sight in the guise of friendly caretakers. See for yourself...this blindfold is soaked in demon blood. Take it north up the hills to Jadefire Run and place it on your eyes. It will show even the most oblivious fool the true nature of any demon.", progress = "Don't tell me you would leave the demons to walk among us unopposed?", completion = "Enough! Your enthusiasm is impressive, but foolish. Gazing through the veil for too long without practice will break your mind.\n\nThe rest will be mine, {name}. For now, I summon you back to me.", objectives = "Slay 12 Jadefire Shifters in Jadefire Run.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28262] = { id = 28262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Veruca Darkstream", description = "Veruca Darkstream, one of the senior rogue trainers in Stormwind's SI:7, has sent word that he wants to speak with you. Head to Stormwind as soon as you can and look for her in the Training Hall south of Old Town.", completion = "Welcome, {name}. We have much to discuss.", objectives = "Speak with Veruca Darkstream at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28263] = { id = 28263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Frazzle Frostfingers", description = "I just received a message from Frazzle Frostfingers, the senior mage trainer in Stormwind. He's asking you to join him at the Training Hall in Stormwind as soon as you can travel there.", completion = "It's good to see you again, {name}. Stormwind has need of your skills.", objectives = "Speak with Frazzle Frostfingers at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28264] = { id = 28264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navarax's Gambit", description = "I have been preying on these demonic impostors for some time now, and I have finally gleaned the location of their leader. It is none other than Arch Druid Navarax, the leader of the Emerald Circle.\n\nThe demon shields himself with innocents. If I entered Whisperwind Grove to hunt him, I would be set upon by ignorant protectors... but you! You can catch him unaware.\n\nReturn to Whisperwind Grove. Climb the druid tower and you'll find Navarax at the top, in his room amidst the boughs.", completion = "I find it hard to believe everything you say, but the body of that demon is grim proof.\n\nI will order an investigation into the druids at Jadefire Run right away, and make sure my higher-ups know the demon hunter may be content to remain in exile.", objectives = "Slay the demon impersonating Arch Druid Navarax.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28265] = { id = 28265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Thorg'izog", description = "Kaoshin turned out to be more helpful than I expected, but we're done with him.  It's time you spoke with the General.  I think you're ready.\n\nGeneral Thorg'izog is one of the \"big three\" that run the ground forces here in Burning Steppes.  He does so from the Blackrock Stronghold to the northwest.  Put on your disguise and go speak with him.  See if you can earn his trust.  Troteman will be in touch, should we need anything further.", completion = "More outsiders?  What do you want?", objectives = "Speak with General Thorg'izog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28266] = { id = 28266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial by Magma", description = "I suppose I'll make the most of this situation.  These goblin mercenaries brought this enormous fire elemental to my stronghold as a \"thank you\" for hiring them.  What am I going to do with an elemental here in the steppes?  That's like bringing sand to the beach.\n\nIf you're looking for work, then prove yourself.  Talk to this goblin here, and challenge his elemental to a fight.  The victor earns my respect, and my time.", progress = "What's the matter, are you scared?", completion = "I had a feeling you'd be the one returning to me.  I like your style, soldier.", objectives = "Speak with Wyrtle Spreelthonket and ask him to release Magma Lord Kolob. Then defeat Magma Lord Kolob in battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28267] = { id = 28267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firing Squad", description = "Come out back vizh me, {race}.\n\nZhere is somezhink I vould like you to see.", completion = "So, this Schnottz character is working with Deathwing!?\n\nThis is even more distressing than you think...", objectives = "Speak to Commander Schnottz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28268] = { id = 28268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Ezul'aan", description = "Ezul'aan from the Training Hall in Stormwind has sent a message for you. He wants to speak with you the next time you're in the city. The Training Hall is located in Stormwind's Old Town District.", completion = "I wish had good news to share with you, {name}, but the truth is that I have asked you here because we have need of your talents.", objectives = "Speak to Ezul'aan at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28269] = { id = 28269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me In Vir'sar", description = "So, listen to this, {name}.\n\nI knew that these obelisks were linked to the Coffer of Promise, but there's more to it.\n\nThere appears to be something very important about the coffer - something pertaining to a place the Makers called the Halls of Origination.\n\nNow that we know this Schnottz fellow and his crew are in league with Deathwing, it's all the more urgent that we get to it first.\n\nI'll wait for you north of here, at the Oasis of Vir'sar\n\nHurry! They have a head start on us!", completion = "Ahh, glad you could make it.\n\nI could use a hand here.", objectives = "Speak to Harrison Jones at the Oasis of Vir'sar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28270] = { id = 28270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding Shotgun!", description = "Alright, {name}, I'm very close to learning how to activate the final obelisk.\n\nOnly a few pieces of information are missing and with any luck, we should be able to find them at the site.\n\nThe supplies are all packed up. Let me know when you're ready to go.", objectives = "Accompany Harrison to the Oasis of Vir'sar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28271] = { id = 28271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduced Productivity", description = "Alright, {name}, here's what I've learned.\n\nThere's a titan device deep in a place called the Halls of Origination. It's meant to be an emergency reset switch for all life on Azeroth. If activated, it will destroy every living thing in the world!\n\nNow, it's only meant to be used under certain extreme conditions, but if Deathwing is able to corrupt the titan watchers, he could use the contents of the coffer to trigger the device.\n\nGo to the Obelisk of the Moon, {name}. Slow them down!", completion = "Good job with Schnottz's men.\n\nSounds like you gave them something to think about.\n\nHopefully it bought us the time we need.", objectives = "Kill 15 Schnottz Excavators or Schnottz Overseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28272] = { id = 28272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Pieces", description = "There are just a few specific pieces of information that I'm missing.\n\nOnce those blanks are filled, we'll be ready to activate the final obelisk. Then, it'll be a race to discover the Coffer of Promise before Schnottz and his cronies can.\n\nThose fools are excavating this site as fast as they can. They're ruining more than they're looting!\n\nGo to the obelisk and rummage through their booty, {name}.\n\nSee if you can find our missing pieces.", progress = "Were you able to find anything interesting, {name}?", completion = "<Harrison quickly skims through the scrolls.>\n\nYes... yes... perfect!\n\nI'll need some time to make sense of these, but the information is there.\n\nGood work, {name}!", objectives = "Collect 7 Ancient Copper Scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28273] = { id = 28273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend of a Friend", description = "I need to unpack and look around the area a bit. In the meantime, I have an old friend I'd like you to meet.\n\nSullah and I go way back. He's a man who can be trusted, and that's pretty rare these days.\n\nWhy don't you go on over and introduce yourself.", completion = "Welcome {class}!\n\nYou and I are going to be good friends! I can tell already.", objectives = "Harrison wants you to speak to Sullah at Oasis of Vir'sar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28274] = { id = 28274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two Tents", description = "Look at you, my friend. This grand adventure of yours has you in knots!\n\nYou need to relax and unwind. You're too tense, and that's just going to tire you out.\n\nTrust me, I know about relaxing!\n\nSpeaking of tents, I see Jonesy brought me the ones I asked for.\n\nCome, friend. Ride with me!", completion = "Here we are, {name}!\n\nGreat things will happen here... magical things!", objectives = "Accompany Sullah to Sullah's Sideshow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28275] = { id = 28275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away!", description = "The Wellson Shipyard is constantly receiving supplies from offshore and we need to put a stop to it.  They have setup cannons along the docks for defense but if you can make it to them, we can use them to destroy their supply ships.\n\nHead over there and see what you can do.  Report back to me on your progress.", completion = "Great work on those supply ships, {name}!  We knew you would be good for somethin' around here.", objectives = "Destroy 10 Ghastly Supply Boats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28276] = { id = 28276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet's Secret", description = "Listen, {name}.  Before you give up on me, there's something I'd like to show you.\n\nYou see, I'm not much of a fighter.  I'm not very coordinated.\n\nI'm more of a tactical mind.\n\nMeet me at the southern end of the ridge and I'll show you.", completion = "Aren't they beautiful?", objectives = "Find Salhet at the Southern End of the Sunwatcher's Ridge in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28277] = { id = 28277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet the Tactician", description = "Ever since I was a cub, I've always wanted to be a general.\n\nI was eager to join the army.  But as you've seen, my combat skills are not all quite there.\n\nThis is not the first time I've been sent to kill hyenas.  As a matter of fact, I get sent here so often, that I've befriended these lions and trained them to do my bidding.\n\nThey are my soldiers and at my command they will slay legions of hyenas.  Watch!", progress = "Did you see, {name}?", completion = "Not bad, huh?  Maybe you can put a word in with the high commander.\n\nMaybe he'll put us in charge of our own squad!", objectives = "Speak to Salhet and slay 30 Bloodsnarl Scavengers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28278] = { id = 28278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Law and I Am the Lash", description = "I've been looking for a good, strong soldier like you.  I need someone to keep my troops in line.\n\nOutside the stronghold, you will find orcs, ogres, and trolls preparing for the assault on Redridge.  My sergeants keep them in line, but I'd like you to assist them.\n\nTake this cudgel and discipline a few of my soldiers.  I don't care if they're misbehaving or standing perfectly in line, I want them beaten.  I want them focused, battle-hardened, and obedient.\n\nNow go.", completion = "I have a feeling we'll be hearing about you and your exploits for a long time, soldier.  I look forward to fighting by your side in Redridge.\n\nYou are dismissed.", objectives = "Use the Blackrock Cudgel of Discipline on 20 troops in the Fields of Honor. If one of the troops discovers your disguise, cudgel him to death before he can unmask you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28279] = { id = 28279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abuse of Power", description = "{name}?  Troteman here.\n\nIt sounds like you have earned Thorg'izog's trust, and he's assigned you to discipline duty.  This is fortunate.\n\nWe need you to take out his sergeants.  You'll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You'll have to act fast, because if they realize you're not one of them, they can unmask you.  Strike quickly and ferociously, {name}.\n\nTroteman out.", completion = "Without those sergeants, Thorg'izog will be hard-pressed getting his troops ready for battle.\n\nAlready the dominoes are beginning to fall, {name}.", objectives = "Kill 5 Blackrock Sergeants using the Blackrock Cudgel of Discipline. Defeat them quickly, before they have a chance to unmask you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28280] = { id = 28280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear Them From the Sky!", description = "Egah! They're here, {name}. They're here!\n\nI had hoped to equip a whole army with my shoulder-mounted drake-droppers, but all I have is a single, extremely expensive and wholly untested prototype. Here, take it!\n\nShoot the Dragonmaw black drakes that are circling Thundermar, and drop them from the sky!", completion = "You did it, {name}! Alliance ingenuity to the rescue.\n\nOf course, I don't have anything to help you fight the dismounted riders now that they're on the ground. You're a {class}; improvise!", objectives = "Use the Shoulder-Mounted Drake-Dropper to slay 8 Dragonmaw Black Drakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28281] = { id = 28281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Stand at Thundermar", description = "I'll hand it to you and your Alliance friends. You've really worked the Dragonmaw over!\n\nMany of their riders are dismounted but they're still coming at us, and my defenders will be overrun without help.\n\nKill Dragonmaw Skyclaws on foot and Thundermar will forever be in your debt!", completion = "You sure know your way around a battlefield, {class}. It looks like they're about to fall back.\n\nAll we need is one decisive blow...", objectives = "Kill 8 Dragonmaw Skyclaws on foot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28282] = { id = 28282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, The Drake-Tamer", description = "There's one Dragonmaw among this lot, the one they call \"Narkrall: The Drake-Tamer.\" I don't know where he gets his power over those beasts, but the black terror he rides is as nasty a brute as ever took the skies over the Highlands.\n\n{name}, Narkrall is the fiend who took my father's life and left Thundermar in my hands.\n\nI can't take him on alone, but I've seen what you're capable of, {class}. Maybe together we can end this.\n\nLet me know when you're ready, and we'll fight Narkrall together!", completion = "We did it, {name}! Narkrall Rakeclaw lies dead at my feet, and Thundermar has weathered a storm of drakes!\n\nThis wouldn't have been possible if it weren't for the help of the Alliance. I owe you a debt that I don't think can ever be repaid.", objectives = "Slay Narkrall Rakeclaw. Speak with Colin Thundermar when you're ready.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28283] = { id = 28283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's that Rattle?", description = "Did you see that glowing rattle on the ground outside of Isha's hut?", sourceObjective = "Inspect the Rattle of Bones on Darkcloud Pinnacle in Thousand Needles.", completion = "Interesting....", sourceObjectiveStatus = "unverified-source-field" }
quests[28284] = { id = 28284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's that Rattle?", description = "Did you see that glowing rattle on the ground outside of Isha's hut?", sourceObjective = "Inspect the Rattle of Bones on Darkcloud Pinnacle in Thousand Needles.", completion = "Interesting....", sourceObjectiveStatus = "unverified-source-field" }
quests[28285] = { id = 28285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Patrice Lancaster", description = "I just received a scroll from the Training Hall, {name}. Patrice Lancaster sends word that she wishes to speak with you. You should meet with her as soon as you can.", completion = "The Light has answered my prayers. At last, you have arrived.", objectives = "Speak with Patrice Lancaster at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28286] = { id = 28286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough Damage For One Day", description = "We do not have any further strategic need for Thorg'izog or the Blackrock ground troops.  We must continue to the next phase of the plan.\n\nWhen you are finished at the stronghold, return to us here in Chiselgrip.", completion = "You alright?\n\nGood.  You did a fine job out there, {name}.  Now pack up your things.  We're moving out of here.", objectives = "Return to Colonel Troteman at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28287] = { id = 28287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Mulric Boldrock", description = "Mulric Boldrock's messenger just reached me, {name}. He has an important matter he wishes to discuss with you and sends word that you should meet him at the Training Hall in the Old Town district in Stormwind as soon as you can make it there.", completion = "Welcome, {name}. We will need your skills in the continuing battle against Twilight's Hammer.", objectives = "Speak with Mulric Boldrock at the Training Hall in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28288] = { id = 28288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open Their Eyes", description = "Before you go...\n\nI've taken advantage of my \"alone time\" with Impsy here to learn some interesting facts about imps. Specifically, he ended up telling me the one thing that all imps fear most. Something they're absolutely terrified of.\n\nI thought that sounded useful as well as interesting, so I've done some basic conjuring. This prism will project an image of... well, of what Impsy described.\n\nShadowlurk Ridge is still swarming with imps. Why don't you go test their reaction for me?", progress = "Having fun?", completion = "I see... their eyes are open\n\n<Delaris smiles with bemusement.>\n\nMaybe I'll keep Impsy around after all. He's got a lot to teach me...", objectives = "Use Delaris's Prism to terrify 20 Jadefire Imps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28289] = { id = 28289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonglade Calls", description = "I have received word that our brothers in Moonglade have requested your help, {name}. You should travel there and speak with Loganaar in Nighthaven. He will tell you all you need to know.", completion = "It's good to see you again, {name}. I wish I could say that I had happy news.", objectives = "Travel to Moonglade and speak with Loganaar in Nighthaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28290] = { id = 28290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Gormok Ogrefist", description = "Gormok Ogrefist sent an urgent message for you, {name}. He wants you to join him immediately at The Barracks in Orgrimmar's Valley of Honor. He must have a mission of importance for you.", completion = "The Horde has need of your skills, {name}.", objectives = "Speak with Gormok Ogrefist at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28291] = { id = 28291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Camp", description = "What do you think, {name}?  Maybe the High Commander will give me a few men to command.\n\nMaybe we can marshal a regiment together.  What do you think?", completion = "Salhet?  A tactician, you say?\n\nHah!  Very well, if you'll vouch for him, we might be able to arrange something.", objectives = "Return to High Commander Kamses at the Ramkahen Legion post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28292] = { id = 28292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's No Pyramid!", description = "That pyramid at the Maker's Terrace in Uldum is nothing of the sort. It's a giant machine that can be reconfigured for any number of uses.\n\nDeathwing was going to have the Twilight's Hammer turn it into a massive weapon!\n\n{name}, you have to take the portal to get this information to Harrison Jones in Stormwind. He'll know what to do.", completion = "Uldum? What about it?", objectives = "Speak with Harrison Jones at Stormwind Keep in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28293] = { id = 28293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's No Pyramid!", description = "That pyramid at the Maker's Terrace in Uldum is nothing of the sort. It's a giant machine that can be reconfigured for any number of uses.\n\nDeathwing was going to have the Twilight's Hammer turn it into a massive weapon!\n\n{name}, you have to take the portal to get this information to Belloc Brightblade at Grommash Hold in Orgrimmar. He'll know what to do.", completion = "Uldum? What about Uldum? Speak quickly!", objectives = "Speak with Belloc Brightblade at Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28294] = { id = 28294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kirthaven Summit", description = "After the licking we just gave 'em, the Dragonmaw assaults on Thundermar ought to stop. Maybe the Wildhammer do have a place in your Alliance - we Thundermars certainly owe you a debt.\n\nUp in Kirthaven, our Grand Shaman Lachlan MacGraff has been trying to arrange a summit between the surviving Wildhammer family leaders. It's a tall order to get us all to work together, but I'm at least willing to give it a go.\n\nFly up to Kirthaven in the North and talk to Lachlan MacGraff. I'll meet you there!", completion = "Hello, {class}! Keegan Firebeard here has told me all about your heroics down south. Thank you for all of your efforts on behalf of the Wildhammer.\n\nI see Colin Thundermar is right behind you. The summit is ready to begin! Please stay and let's see how things unfold...", objectives = "Speak with Lachlan MacGraff at Kirthaven in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28295] = { id = 28295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meetup with the Caravan", description = "The pyramid inside of the Maker's Terrace in Uldum can be used as some kind of super weapon that will end all life on Azeroth.\n\n<Harrison thinks a moment.>\n\nYou need to continue the research you've begun. Head to the southern end of Kalimdor, to the desert of Tanaris. There's a caravan there that's about to leave for Uldum.\n\nPerhaps you can tag along.", completion = "Harrison sent you, hmm?\n\nHow fortunate!", objectives = "Speak with Adarrah at Thistleshrub Valley in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28296] = { id = 28296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meetup with the Caravan", description = "The pyramid inside of the Maker's Terrace in Uldum can be used as some kind of super weapon that will end all life on Azeroth.\n\n<Belloc thinks a moment.>\n\nYou must continue the good research that you've begun. Head south to the desert of Tanaris. There's a caravan there that's about to leave for Uldum.\n\nPerhaps you can tag along.", completion = "Belloc sent you, hmm?\n\nHow fortunate!", objectives = "Speak with Adarrah at Thistleshrub Valley in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28297] = { id = 28297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Tamanji", description = "I received a scroll for you from Tamanji in Orgrimmar. She wants you to make your way to The Barracks in the Valley of Honor and speak with her as soon as you can. It sounded urgent, {name}.", completion = "The Horde has need of your skills, {name}.", objectives = "Speak with Tamanji at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28298] = { id = 28298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Thega Graveblade", description = "Thega Graveblade, the senior rogue trainer of the Shattered Hand in Orgrimmar, wishes to meet with you. Make your way to Orgrimmar quickly, {name} and seek her out at The Barracks in the Valley of Honor. She must have an important mission for you.", completion = "The Shattered Hand needs your skills, {name}.", objectives = "Speak with Thega Graveblade at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28299] = { id = 28299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Kazak Darkscream", description = "I have just received word from Kazak Darkscream, Orgrimmar's foremost warlock trainer. He wishes you to travel to Orgrimmar and speak with him at The Barracks in the Valley of Honor. It sounds like he has an important mission for you.", completion = "The Horde will soon call upon your skills, {name}.", objectives = "Speak with Kazak Darkscream at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28300] = { id = 28300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Feenix Arcshine", description = "I just received a scroll for you from Orgrimmar, {name}. It's from Feenix Arcshine, one of the mage trainers there. He wants you to meet with him at The Barracks in the Valley of Honor.", completion = "The Horde needs your help in the battle against our enemies.", objectives = "Speak with Feenix Arcshine at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28301] = { id = 28301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Hretar Riverspeaker", description = "An urgent message just arrived for you, {name}.  It's from Hretar Riverspeaker, one of the shaman trainers in Orgrimmar.  He requests your presence as soon as possible.", completion = "These are dangerous times, {name}. The Horde is fortunate to have taurens like you in its ranks.", objectives = "Speak with Hretar Riverspeaker at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28302] = { id = 28302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet with Avaros Dawnglaive", description = "You should make your way to Orgrimmar as soon as you can, {name}. Avaros Dawnglaive has sent word that he wishes to speak with you about a matter of importance to the Horde. Look for him at The Barracks in the Valley of Honor.", completion = "The Horde will soon have need of your skills, {name}.", objectives = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28303] = { id = 28303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet With Avaros Dawnglaive", description = "Avaros Dawnglaive sent an urgent message for you, {name}. He asks you to join him at The Barracks in Orgrimmar's Valley of Honor the next time you're in the city. It sounds as though he must have an important assignment for you.", completion = "You are one of the most promising young paladins I have ever trained, {name}. It is for that reason that I wish to offer you a dangerous mission.", objectives = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28304] = { id = 28304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "Our enemies stir once more, {name}, and you will be at the forefront of battle.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28305] = { id = 28305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Bloodvenom Post", description = "While we dealt with Jaedenar, I sent a friend of mine north to Bloodvenom Post. We used to have infrequent visits from the tauren there, but they have stopped coming as of late.\n\nMy friend, Kelnir Leafsong, has yet to return. Would you travel north to check on her and the situation at Bloodvenom?\n\nShould you find her, do be aware... dryads like her tend to strike other races as a bit odd.", completion = "Oh, hi! Did Farlus send you? I'm so happy he remembered!\n\nBloodvenom post is all overrun with awful slime thingies, and this poor tauren is the only one left! We've got to help him!", objectives = "Speak with Kelnir Leafsong at Bloodvenom Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28306] = { id = 28306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whisperwind Grove", description = "You've been such a big help here!\n\nI'm gonna stay here a while and look after poor Mr. Tauren until he stops throwing up so much. Why don't you head north to Whisperwind Grove? It's really pretty there, and all the druids are so friendly!\n\nYou should tell Miss Puregrove I'm okay, she'll worry if I'm gone too long. She might ask you to help with her flowers, too! So fun!", completion = "Kelnir? Hahaha...\n\nSometimes I wonder if her chatter drove all the other dryads away. But I'm glad she is safe.\n\nWelcome to Whisperwind Grove, {class}. Hold peace in your heart, and you will find a home here.", objectives = "Speak with Tender Puregrove at Whisperwind Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28307] = { id = 28307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "The Horde has need of your talents, {name}.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28308] = { id = 28308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "The Horde has need of your talents, {name}.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28309] = { id = 28309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "The Horde be needin' you, {name}.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28310] = { id = 28310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan's Vigil", description = "Our work here in Chiselgrip is done, mostly thanks to you.  We'll now be moving on to the east, to Morgan's Vigil.\n\nOur intel indicates that Morgan's Vigil has been vacated, as most of its inhabitants have moved into Blackrock Mountain to fight their own battle against the Blackrocks.  It should serve as a sufficient base of operations for the final stages of our plan.\n\nOf course, Keeshan will be joining you on the road.  As will I.", completion = "You've arrived!  And just in time for the friendship ceremony!\n\n<Oralius looks wistfully over his shoulder at the ogre head, and quickly becomes panicked.>\n\nCaptain Winky!  Where'd Captain Winky go?\n\nNo, don't tell me he got cold feet!", objectives = "Report to Oralius at Morgan's Vigil in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28311] = { id = 28311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackened Ashes", description = "I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we're going to do this, we're going to do it right, and that means being prepared.\n\nI need ash, {name}.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the northwest.  The stuff is deep, deep black, which is what we need for our next disguise.\n\nDon't worry, you've already got a disguise.  This one is for someone... well, someTHING... else.", progress = "The ashes of the obsidian elementals are particularly dark - exactly what we need for our purposes.", completion = "Yes, these will do.  I will get this packed up for you.", objectives = "Obtain 9 piles of Obsidian Ash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28312] = { id = 28312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Demons of the Land", description = "The lava beds nearby - to the west - play host to flamekin, a brand of fire demon that has long roamed the steppes.  Situations are such in the Blackrock army that, if we are careful, we may be able to sneak some of these flamekin behind enemy lines to cause some havoc.\n\nBring me the bodies of several flamekin.  As demons, they are easily resurrected, and then we can use them for our own purposes.", progress = "The flamekin are weak, but they travel in packs.  Be cautious.", completion = "To the untrained eye, these will look exactly like imps.\n\nWe just need to get them to that untrained eye.  I'll work on preparing them for delivery.", objectives = "Obtain 18 Fallen Flamekin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28313] = { id = 28313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heap of Delicious Worg", description = "We're going to need fresh meat, which means you're going to be hunting worg.  The worg on this side of the steppes should be your target.\n\n<Troteman produces a large blade, which he hands to you.>\n\nHunt the giant ember worgs.  Once you've killed them, use this saw to remove the choicest bits of meat from their bodies.  You will find these worgs all over the steppes, but the closest pack rules the land just to our northeast.", progress = "Any luck out there?", completion = "This meat looks good... but I think it needs a little \"seasoning\".  I'll make sure that gets taken care of.\n\nThank you, {name}.", objectives = "Use the Worgsaw on the bodies of slain Giant Ember Worgs to obtain 40 Worg Cutlets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28314] = { id = 28314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Tour", description = "My legs are getting a little restless again.  You interested in taking a little tour, {name}?\n\nWe're going to take a trip around Dreadmaul Rock.  I'd like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we're on the way.", completion = "<Keeshan is covered in blood and sweat.>\n\nThat was exactly what I needed.", objectives = "Kill 25 Black Dragonspawn or Black Wyrmkin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28315] = { id = 28315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Vanguard", description = "The Blackrock orcs don't come alone.  You've already seen that they've got the Firegut ogres and Smolderthorn trolls on their side.  Unfortunately for us, they're also teamed up with the black dragonflight.\n\nThe orcs and the dragons have already sent some of their champions to stand guard at rally points, which are marked by a dragon skull on a pike.  You and I are going to find these rally points and take out this vanguard before the battle starts.\n\nReady?", progress = "Come on, {name}, there's still more of them left.  Our job isn't done.", completion = "Your kill count is adding up, {name}.  We're chipping away at them.\n\nAnd we are going to win.  Redridge will NOT fall to these cowards.", objectives = "Slay Minyoth, Whelptamer Akumi, Terromath the Seared, and Tugnar Goremaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28316] = { id = 28316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deal With a Dragon", description = "While we are circling around Dreadmaul Rock, there's one more stop that we need to make.\n\nYou remember the hatchlings that you freed from the Whelping Downs?  Troteman's been hanging onto them, and we're going to deliver them to someone who will take care of them better than we can.  He's staying in Slither Rock, to the northeast of Dreadmaul Rock.\n\nHis name is Acride, and he might be the key to victory in the upcoming battle.", progress = "You've arrived, {name}.", completion = "Yes, the whelplings.  I will take care of them.\n\nAs for the agreement I made with your Colonel Troteman earlier, tell him that I will hold up my end of the bargain.  You will have your dragon for the battle against the orcs.\n\nWe hold no particular love for the Redridge Mountains, but we do share your grudge against the Blackrock clan.", objectives = "Deliver the Rescued Whelplings to Acride at Slither Rock in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28317] = { id = 28317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Thorg'izog", description = "General Thorg'izog is staying among the ogres in the Firegut Furnace, a cave on the western edge of Dreadmaul Rock.  I'd like you to deliver this to him and the ogres.\n\nInside this package, you will find the worg cutlets you obtained, marinated in the fel slider cider that we took from the Altar of Storms.\n\nI would avoid eating it if I were you.\n\nBring it to General Thorg'izog.  He will make sure that his troops are fed and, with any luck, he will eat some himself.", progress = "What've you got there, soldier?", completion = "Well would you look at that!  My favorite soldier comes through in the clutch!\n\nI'll make sure to get this distributed among the ogres.\n\nI'll see you in Redridge, soldier.  For the glory of the Blackrock!", objectives = "Using your Blackrock Disguise, bring the Slider Cider-Marinated Cutlets to General Thorg'izog at Firegut Furnace in Burning Steppes. Speak with Colonel Troteman if you need a new Blackrock Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28318] = { id = 28318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Neeralak", description = "The warlocks of the Blackrock Clan often practice their magic in the Skull Warren, a cave on the eastern side of Dreadmaul Rock.  Their leader, Xi'lun, is busy elsewhere, so the cave is currently being held by another of the big three: Dragon-Lord Neeralak.  And Neeralak's expertise is in dragons, not in necromancy.\n\nI've used the slumber sand on those flamekin you captured.  Try to convince Neeralak that they're warlock imps, and not flamekin.  When they wake up, they won't be happy.", progress = "What?", completion = "What are these?  Oh, are these imps?\n\nI'm pretty sure that imps don't just fall asleep in boxes!\n\nI'll take your word for it, though.  I don't understand any of this warlock crap.  Leave them in the corner.", objectives = "Using your Blackrock Disguise, sneak into the Skull Warren and convince Dragon-Lord Neeralak to take your Crate of Sleeping Flamekin. Speak with Colonel Troteman if you need a new Blackrock Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28319] = { id = 28319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Xi'lun", description = "Intel tells us that High Warlock Xi'lun - the final member of the Big Three - is within the cave atop Dreadmaul Peak, preparing for his big moment.\n\nHe is waiting for a delivery: an Orb of Domination, with which he can perform a powerful summoning ritual.  I want you to give him this:\n\n<Troteman hands you a glass orb.>\n\nThis is the clear glass orb that you freed from the Altar of Storms.  It is powerless.  Give it to Xi'lun, and cross your fingers that he doesn't notice.", progress = "I don't have time for games, fool.  Get out of my sight.", completion = "Pff!  You're late!  Do you know how long I've been waiting for Ner'gosh to deliver this orb?\n\n<Xi'lun looks down at the orb, then up at you.>\n\nThere's something strange about this orb... it's too...\n\n<Xi'lun trails off.>\n\nNever mind, it must be my nerves talking.  Thank you for the delivery.  For blood and honor!", objectives = "While using the Blackrock Disguise, deliver the Clear Glass Orb to High Warlock Xi'lun atop Dreadmaul Rock in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28320] = { id = 28320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Dreadmaul Rock", description = "This is it, {name}.  This is where it hits the fan.  Where all the pieces come together.\n\nStrap in, and come with me.  We're going to go talk to Acride and call in that favor that he owes us.  Then we'll stop this invasion of Redridge before it even starts.", progress = "Now's our chance!  Crush them!  We won't get another opportunity like this!", completion = "Did you see them run?  They didn't know what was happening!  Beautiful!\n\nOur job's almost done, {name}.  It's time to deliver the deathblow.", objectives = "Slay 200 Blackrock Invaders. If you should lose your vehicle, use the Horn of the Callers to summon it again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28321] = { id = 28321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glory Amidst Chaos", description = "You and Keeshan are going back to that mountain.  There's three orcs who survived the attack, and we won't rest until they're dead.\n\nThat's right, I'm talking about the Big Three.\n\nGeneral Thorg'izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain's peak.  Xi'lun is in the back of the Skull Warren, plotting with his fellow warlocks.\n\nLeave your mark, {name}.  Hunt down those sniveling Blackrocks, and teach them the might of Redridge!", completion = "<Colonel Troteman is beaming.>\n\nWelcome home, boys.", objectives = "Kill General Thorg'izog, Dragon-Lord Neeralak, and High Warlock Xi'lun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28322] = { id = 28322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spoils of War", description = "We've toppled a giant today, {name}.  While the Blackrock orcs still swarm in their spire, I doubt their plans will take them anywhere near Redridge anytime soon.  You and Keeshan saw to that.\n\nI'd say we were fairly resourceful here in Burning Steppes - those warlock supplies we collected certainly came in handy, as did the obsidian ash that we used to conceal our dragon.\n\nThere were, however, some collected items left over.  Please, take your pick before you move on, beyond the steppes.", completion = "You peer inside, and find...", objectives = "Inspect the Box of Left Over Supplies at Morgan's Vigil in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28323] = { id = 28323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", completion = "So you got my message. Good. I have an important task for you.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28324] = { id = 28324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Studies in Lethality", description = "We used a fairly potent strain of blight against the humans of Southshore. As you can see, it worked. The trouble with blight use, though, is that blight tends to stick around after it's served its purpose.\n\nWhat I need from you is to take this testing kit and get out into the field to get a lethality count from the blight slimes that we've released into the area. Use the lethality analyzer on the blight slimes sweeping the slime pools. Come back to me when you have some solid data.", completion = "Oh my. 250? This thing doesn't go past 250. How are you still standing? You should be a puddle of goo by now. Sylvanas will be most displeased with this information. There might be some things we can do to reduce the lethality levels of the area by a few decades, but that still leaves us out by about a hundred or so years.", objectives = "Recover 250 Blight Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28325] = { id = 28325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Living", description = "Recycling! It's all the craze these days. The Banshee Queen has decreed that we must conserve if we are to prosper as a people. Everyone must do their part, right? With that said, you will be doing our part for us.\n\nThere are likely thousands of blight canister bits and pieces all over Southshore. We can reuse those canisters for more blight bombing goodness. Just head into the ruins here and pick up whatever you can find.", progress = "Bring me those canisters!", completion = "Excellent work, {name}. You are incredibly resilient to this blight. We'll have to take you in for testing some time.", objectives = "Recover 8 Used Blight Canisters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28326] = { id = 28326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placing the Pawns", description = "{name}.  It sounds like you and Keeshan have finished with your tasks.  I've also finished mine.\n\nReturn to Morgan's Vigil.  I've prepared a few packages to deliver to the Big Three: Thorg'izog, Neeralak, and Xi'lun.  You've already met General Thorg'izog.  This will be your chance to meet the other two.\n\nThat is, before we kill them.", completion = "Good, you're back.\n\nI hope you've still got that disguise.  You're going back undercover, {name}.", objectives = "Return to Colonel Troteman at Morgan's Vigil in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28327] = { id = 28327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locked and Loaded", description = "{name}, come in.  Can you read me?\n\nThe battle is about to start.  I hope you've delivered all of those packages.\n\nI need you here in Morgan's Vigil, NOW.", completion = "{name}'s here!  We can get started.\n\nThis is our big moment, {name}.  I hope you brought your A game.", objectives = "Report to Colonel Troteman at Morgan's Vigil in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28328] = { id = 28328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer reaches far and wide. They search ceaselessly for allies in their battle against us and they are recruiting the Dark Iron dwarves of Blackrock Depths to their cause.\n\nMoira's grip on the Dark Irons is tenuous at best and more of her people fall away from her rule with each day. We must sabotage their recruitment efforts.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", progress = "We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", completion = "You have done your work well, {name}. While this will not stop Twilight's Hammer, it will help sow suspicion between them and the Dark Irons.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28329] = { id = 28329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angry Scrubbing Bubbles", description = "These blight slimes seem to be really angry. They've even got a faint outline of an angry humanoid face in their ectoplasm. You don't think Hinott would be too happy about having non-compliant slimes working the slime pools.\n\nKill any angry blight slimes that you see and try to get a lock on a breeding pool.", completion = "All signs indicate to a breeding pool being inside the ruined town hall. You'll need to investigate!", objectives = "Kill 5 Angry Blight Slimes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28330] = { id = 28330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail of Filth", description = "The trail of filth and anger leads into the ruined town hall. Surely there is a slime breeding pool inside the structure. Fight your way inside and deal with whatever angry slime-breeder that you encounter!\n\nShould you succeed Serge Hinott at the Ruins of Southshore will surely want to hear about it.", completion = "Perhaps with Chet vanquished, the lethality levels of this place will decrease a tad faster. A job well done, {name}!", objectives = "Kill Chet the Slime-Breeder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28331] = { id = 28331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helcular's Rod Giveth...", description = "To think, I, a master of necromancy, trained by Kel'Thuzad himself, was reduced to nothing more than a corpse in a grave. Thankfully, my astute apprentice, Thaivand, managed to find a group of heroes to recover this:\n\n<Helcular whips out his rod.>\n\nIt is through the power of the rod that I was reborn. The rod giveth and the rod taketh away!\n\nTake it now and use it to empower our dark rangers battling the worgen in the field north of us. Renew their vigor with my rod.", completion = "As I said, the rod giveth to our dark rangers and doth taketh away from our enemy!", objectives = "Use Helcular's Rod to Empower 8 Dark Rangers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28332] = { id = 28332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helcular's Command", description = "Our dark rangers search the fields for worgen terrorists. These worgen have been sent out by their dark masters to hunt and kill us. And though a dark ranger is a formidable combatant, the worgen often attack in packs, which can overwhelm even a dark ranger.\n\nSearch the fields around the ruins of Southshore for Bloodfang forsaken hunters. Kill any that you see! For the Forsaken and for Lordaeron!", completion = "We should have killed Bloodfang in Silverpine. It's a shame he still lives. It's an even bigger shame that we have as of yet been unable to turn worgen into undead. Surely there is a way...", objectives = "Kill 15 Bloodfang Forsaken Hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28333] = { id = 28333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Time to Oil Up", description = "Three things come out of Irontree Clearing: lumber, oil, and exhausted workers. The first two are pretty much the cause of the third, but I like to be efficient about things where I can.\n\nI've got our shredders working triple unpaid overtime, and there's really nowhere in the schedule for them to get maintenance.\n\nUse this grappling hook to nab some of the extra oil cans floating around camp and use them to oil up the shredders, would you?", completion = "Efficiency in the workforce! Wonderful.\n\nMaybe I should check on the goblins inside those shredders later.", objectives = "Use Darla's Grapple to collect Irontree Oil Cans and use them to oil 7 Irontree Shredders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28334] = { id = 28334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flare Fight", description = "This operation's stayed pretty discreet so far, but the worgen over in Talonbranch Glade have it out for us. They've been trying everything they can to get us shut down.\n\nSome of the workers have told me they've seen glimpses of worgen lurking around the clearing. Take these oversized megaflares. They're bright enough to show anything that gets anywhere near them.\n\nUse the flares to look for prowling worgen, and make sure they don't leave here alive!", completion = "Mangy curs think they can just waltz in here and ruin my finely-tuned operation. Hah!\n\nI told you not to look directly at the flares, right? Oops.", objectives = "Use Darla's Box of Megaflares to reveal 8 Talonbranch Prowlers and slay them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28335] = { id = 28335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn It Off! Turn It Off!", description = "It was those darn worgen! They blew right past me into the cavern.\n\nThey must've messed with the Master Control Pump! If that thing is left on too long, every pipe runnin' under our feet is gonna blow. You think the leaks now are bad? Just wait!\n\nListen, if you can reach the Master Control Pump all the way in the back of the cavern, you can shut it off and save us all!", completion = "You turn the largest handle you can find on the Master Control Pump, and the rattling noises in the nearby pipes stop.\n\nThis gives you a few moments to hear the sound of flames outside before a familiar voice cuts in through a tinny, craclikng speaker.", objectives = "Shut off the Master Control Pump at the bottom of Irontree Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28336] = { id = 28336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slap and Cap", description = "Oh for... not again! If you heard the deputy yelling out there, that means we've got a fullblown oil leak on our hands! It's those filthy worgen again!\n\nListen, it's going to be total chaos out there. Sleep-deprived goblins running around screaming and not knowing what to do. I need you to snap the workers back to their senses.\n\nA good, swift backhand across the face should do it! Once they shake themselves off, they'll get to work capping those gushers!", completion = "It's not working! We're going to have to shut it off at the source.\n\nGo talk to the Deputy outside, he'll walk you through it!", objectives = "Slap 7 Panicked Workers to make them cap the oil gushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28337] = { id = 28337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shredders of Irontree", description = "Disgusting, isn't it? Look at them. Pathetic little things that can't even toil with their own bodies.\n\nThey stomp around in their massive metal shredders, carving the forest to splinters. I bet they think they're safe in there, all warm and cozy.\n\nProve them wrong. Blaze north through the camp and destroy as many shredders as you can. Once you've spilled some blood, we're going to take this place apart for good.", progress = "Is the attack complete?", completion = "This is but the first strike.", objectives = "Kill 9 Irontree Shredders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28338] = { id = 28338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.\n\nPlease, {name} - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.", completion = "I sense that you have achieved victory.  Victory... such a hollow word considering what had to be done.  Regardless, you've proven yourself to be worthy of our trust.\n\nIt may take some time before the Timbermaw welcome you without hostility within the Hold.  Still, your perseverance will erode any suspicion my brethren may have about you.  So long as you never betray us and raise weapons against us, we will find common ground.", objectives = "Kill 15 Deadwood Furbolg of any kind in Felpaw Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28339] = { id = 28339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is Your Oil Running?", description = "Last time we had an oil leak this bad, the oil itself tried to get away!\n\nI don't know what does it, maybe all the demon goop floating around here, but when we get a big enough crude leak half of it globs together and tries to run away.\n\nThat's profit trying to escape! Go run after those oil sludges and bring back their sweet, precious oil!", progress = "That stuff better not still be moving when you bring it back here.", completion = "Thank goodness the oil is safe! Well done, {name}.", objectives = "Collect 10 Crude Tarballs from Oily Sludges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28340] = { id = 28340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bomb Deal", description = "All my workers got driven straight out of the cavern here by those big swamp-lookin' things! Darla's sent me here to pick up the pieces, but have you seen it in there? I ain't goin' in!\n\nThere's a ton of explosives left behind that we can't just leave layin' around.\n\n I'll make you a deal: You run in there and get those explosives gathered up, and I will stay here and not get killed by swamp-things, and if you don't either, I'll pay ya! How's that sound?", progress = "We had a deal, right? Right?", completion = "Hey, nice! I'll just take those... carefully...\n\nDon't go tellin' the workers I didn't have the guts to go down there myself, you hear? Here's your pay... and a little somethin' extra.", objectives = "Collect 8 Irontree Explosives from Irontree Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28341] = { id = 28341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collecting Corruption", description = "Though we druids shun the demonic powers infesting this land, it must still be confronted.\n\nShatter Scar Vale to the south seethes with corruption. The energies there are so chaotic that they manifest as violent entities, pure fel magic given form to lash out at all life.\n\nI have been keeping a close eye on these chaotic beasts, and studying their strength. I need to make sure they are still weakening with time. Bring me the essences they drop, so I may ensure they are diminishing.", progress = "Be wary with the essence. It is as poisonous as it is powerful.", completion = "I can tell just from the size of these that the fel taint is healing. Slowly... but significantly.\n\nThank you, {name}. I will ensure these are properly purged.", objectives = "Collect 8 Entropic Essences from Entropic Horrors in Shatter Scar Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28342] = { id = 28342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel To Pieces", description = "The infernals that lurk in Shatter Scar Vale are formidable, but not invincible. Much progress has been made in thinning their numbers.\n\nDestroying them is only part of the solution, however. I've found that the stone that infernals are made of still contains large amounts of fel magic even after the infernal's death.\n\nThe rubble of slain infernals now litters Shatter Scar Vale, leeching its corruption back into the ground. If you could collect it and bring it to me, I would be grateful.", progress = "Do be sure to pick up after your own kills, as well.", completion = "It's good to see someone who cares about keeping the forest clean. Thank you, {name}.", objectives = "Collect 9 pieces of Infernal Debris from Shatter Scar Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28343] = { id = 28343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Breath of Cenarius", description = "{name}, we have learned that a missing Cenarion artifact has surfaced in the hands of a Twilight's Hammer pyromancer. Pyromancer Loregrain has taken this artifact, the Breath of Cenarius, into Blackrock Depths and uses its power to open elemental gates.\n\nWe must act to keep Loregrain from summoning elementals to bolster the ranks of his Dark Iron allies. Recover the artifact from him and use its power to close the gates that Loregrain has been using.", progress = "We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", completion = "I'm heartened to have the Breath of Cenarius back where it belongs and I know the rest of the circle will be impressed by your efforts. You may have also set back the plans of the Twilight's Hammer clan a bit, too. Excellent work.", objectives = "Recover the Breath of Cenarius from Pyromancer Loregrain in Blackrock Depths and use the artifact to close 3 Elemental Gates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28344] = { id = 28344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can You Smell What the Lok'tar is Cooking?", description = "Shortly before you arrived an orc flew in upon a frost wyrm and demanded that I direct him to where the 'newbies were hanging out.' Uncertain as to the vernacular, I told him to fulfill his duty as a member of the Horde and deal with the worgen threat of the area. He grumbled something about 'what the lok'tar was cooking' and headed south to the docks.\n\nOrdinarily I wouldn't care about whether or not an orc went missing, but I am genuinely curious about what the lok'tar might be cooking. Find out.", completion = "*GASP*\n\nHELP!\n\nDROWNING!\n\n*GURGLE*", objectives = "Find Kingslayer Orkus at the Ruins of Southshore in Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28345] = { id = 28345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "*Gurgle* HELP! *Gurgle*", description = "*GURGLE*\n\nHELP!*GASP*\n\nORKUS IS DROWNING! HELP ME, QUEST GIVER {name}!\n\n*GLUB*\n\nDwarf threw Orkus into the water! Must not die!\n\n*GURGLE*\n\nThe shame would be too great.", completion = "<Orkus' face turns as red as his armor.>\n\nI... uh... the human must have cast some type of mind-altering spell on Orkus. Orkus will explain.", objectives = "Help Kingslayer Orkus get out of the water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28346] = { id = 28346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bachelor", description = "We need to make this work, {name}. The answer is in the blood! Family bonds have kept these Wildhammer clans apart from one another. It'll take family bonds to glue 'em back together. It's a long shot, but we're going to have to play matchmaker!\n\nI'll track down Colin Thundermar and talk with him. You're a smooth one - you should talk to Keegan Firebeard inside. He's sharp enough to understand a political marriage. Go find out if he fancies anyone!", completion = "What? Kurdran's talkin' marriage!? Didn't he just see me an' ol' Thunderface tearing each other new ones?\n\nThe only eligible Thundermar is Fanny. Now, I'll give you this, she's got the looks allright. All lumpy in the right places, if you hear me. But she's not got that somethun' somethun' a Firebeard looks for in a woman, right?", objectives = "Discuss marriage prospects with Keegan Firebeard at Kirthaven in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28347] = { id = 28347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coffer of Promise TRACKING QUEST" }
quests[28348] = { id = 28348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike Rendezvous", description = "I tracked down the decrepit necromancer, Helcular, in hopes of getting a lead on Alliance movement within Hillsbrad.\n\nHelcular tasked me with finding and killing worgen. Ordinarily this would not be a problem for Orkus, but I had just eaten several helpings of Dirge's Kickin' Chimaerok chops, causing my bowels to cry out in anguish. That's when the trouble began and how I ended up in the water.\n\nHear Orkus out, {name}.", completion = "I will have my vengeance, but first we must heal Kasha.", objectives = "Learn about the Stormpike Rendezvous from Orkus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28349] = { id = 28349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megs in Marketing", description = "Boss, while you were down at the mines, Megs Dreadshredder in marketing was asking for you. Something about your \"new image\" or whatever.\n\nShe's right outside the building to the left.", completion = "There he is! I think you're going to like this!", objectives = "Speak with Megs Dreadshredder at KTC Headquarters on Kezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28350] = { id = 28350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Trapper", description = "One thing about me that you might not know, {name}...\n\nI come from a long line of trappers. My father taught me, as his taught him, to master the art of trapping creatures in a most merciful manner.\n\nAs any master trapper will tell you, the most important ingredient in an effective trap is the bait.\n\nSo let's start there.\n\nFill this bucket with the meat scraps from almost any wild creature in Uldum.", progress = "Have you got enough to fill my bucket, {name}?", completion = "Fine work, my boy!\n\nYou'll master this trapping skill in no time.", objectives = "Sullah wants you to collect 5 Meat Scraps from the wildlife in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28351] = { id = 28351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlimited Potential", description = "Some see the little sand pygmy as nothing more than a pest, a vermin, or worse yet, a vile little demon.\n\nI say they are simply misunderstood!\n\nWith the proper care and guidance, these little fellows may just turn out to be a glorious gift of nature.\n\nI would like you to take these cages and use them to capture a few of them for me to work with.\n\nYou will need to give them a sound beating before boxing them up, but in the end it will be for their own good.\n\nYou'll see!\n\nGo south for pygmies!", completion = "Splendid!\n\nThis is shaping up to be better than I had dared to dream!", objectives = "Use the Reinforced Cage to capture 5 Cavorting Pygmies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28352] = { id = 28352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camelraderie", description = "Greetings, friend!\n\nYou are always most welcome in my humble tent.\n\nLooking for something to do? Sullah has just the thing!\n\nCamels are good to have in hand regardless, but when putting together a performance the likes of my sideshow, they are an absolute must!\n\nTake this harness and use it to subdue a wandering camel.\n\nYou may have to, uhh, humble it a bit first... if you know what I mean.\n\nYou'll find a desert full of wild camels to the south.", completion = "You've done it!\n\nI now have camels to spare. Perhaps one day we shall take our show on the road!", objectives = "Use Sullah's Harness to tame 3 Camels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28353] = { id = 28353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jonesy Sent For You", description = "Listen, {name}, you may want to make your way back to Jonesy when you get a moment.\n\nChances are, whatever he's got to talk to you about is more pressing than anything I have for you to do.", completion = "Alright, kid.\n\nMy research is complete. We're about ready to activate the final obelisk.", objectives = "Speak with Harrison Jones in the Oasis of Vir'sar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28354] = { id = 28354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kasha Will Fly Again", description = "Kasha will fly again, {name}. She must if we are to claim vengeance! Sadly, Orkus must stay here with Kasha. You must help us. I beg of you!\n\nListen carefully, quest giver. When I first arrived here I flew around for days to learn the lay of the land. There is a farm east of here that has long since been abandoned and is now overrun by gnolls. On this farm grows a special type of mushroom known as the mudsnout. Go to the stead and gather mudsnout for Kasha. Return here when your pack is full.", progress = "Have you recovered the mudsnout?", completion = "This mushroom is toxic to living things, but provides a restorative boost to the undead. Let us see how Kasha reacts.", objectives = "Gather 8 Mudsnout Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28355] = { id = 28355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrible Little Creatures", description = "Gnolls! These terrible little creatures are a blight upon any land - which is saying a lot when you consider that Hillsbrad is Forsaken territory. Kill as many of the gnolls at the Nethander Stead as you can. For the good of the world!", objectives = "Kill any 10 Gnolls at the Nethander Stead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28356] = { id = 28356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preemptive Strike", description = "These plans document what appears to be an imminent attack on Southshore. The naga of the Eastern Strand are planning to take over the town now that the Alliance has been pushed out.\n\nNot if you can help it!\n\nKill all of the naga on the Eastern Strand and report to Helcular at the Ruins of Southshore with the Daggerspine attack plan.", completion = "HAH! Those naga have some balls on them! To think that they could take Southshore from us in our own territory! Such a preposterous notion.\n\n<Helcular laughs.>\n\nYou have done well to thwart their attack - though I do wonder if they could have survived for even a minute in the blight.", objectives = "Kill any 15 Naga at the Eastern Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28357] = { id = 28357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take it to the Tree", description = "Those mangy curs think they can just snoop around my site and get away with it? I'll show them...\n\nAnd what I mean by that is, of course, that YOU will show them. You and the small army of axe-wielding goblin hires I've sent to Talonbranch Glade.\n\nThe place will be swarming with worgen by now. Just where we want them. Head to the southeast, join up with the rest of our forces, and let some fur fly.", completion = "Let's hope we put down enough of them to get the message across.", objectives = "Slay 8 Talonbranch Defenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28358] = { id = 28358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Damned", description = "The first demons to set foot in this forest were infernals. Long ago, these powerful beings of stone and demonic fire fell from the sky to take this land for the Burning Legion.\n\nThe charred craters of Shatter Scar Vale to the south are where these infernals landed, and many still wander there. They are fierce foes, and killing them is both a worthy challenge and a noble cause.\n\nI offer reward for those who join the hunt. Return here afterwards.", completion = "I thank you for hunting in my stead, {class}.\n\nI've found I must pace myself... finding too much thrill in hunting demons is a dangerous path.", objectives = "Slay 6 Infernal Sentries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28359] = { id = 28359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Core of Kroshius", description = "The most fearsome demon in Shatter Scar Vale is known as Kroshius. Though many have hunted him over the years, destruction has only made him stronger.\n\nTime after time, warlocks have come to this forest and reanimated Kroshius. He now lurks in the southeast, surrounded by demonic fire, awaiting any who come to try and claim his power.\n\nI will not have this corrupt cycle continue! Kill Kroshius, and bring his infernal core to me.", progress = "The core must be kept away from Shatter Scar Vale.", completion = "This foul chunk is what those warlocks sought year after year. I will protect it myself, or destroy it if possible, and ensure Kroshius never rises again.", objectives = "Obtain Kroshius' Infernal Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28360] = { id = 28360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Their Course", description = "I'd love so much to save every creature in the forest, but as you probably have seen, some are just too far gone.\n\nWhen we first founded Whisperwind Grove, the woods just to the south were full of beautiful coursers, majestic and gentle creatures. The corruption here hasn't made them violent, but they've wasted away to nearly nothing.\n\nEven if they were cleansed, they would know only pain and suffering. Please, {class}, help put them down for me.", completion = "Thank you, {name}. They won't spread the corruption any further, and they won't be in pain either.", objectives = "Slay 8 Felrot Coursers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28361] = { id = 28361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squirrely Clean", description = "The larger animals are often too far corrupted to save, but you'd be surprised how hardy the little ones are.\n\nTake the squirrels, for example. After washing in corrupted water, they can spread illness far from the original source, but it's slow to affect the squirrels themselves. In fact, a simple washing will result in a clean squirrel and a safer forest!\n\nHere, take this bottle of cleaning mixture. Grab and scrub any squirrel you see in the woods to the south... they'll be thankful for it!", completion = "Aren't they just adorable?\n\nIt's those little victories that keep me going. We'll save this forest one squirrel at a time.", objectives = "Scrub 6 Tainted Squirrels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28362] = { id = 28362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stupid Drizle!", description = "Stupid, stupid Drizle! I told him not to go!\n\nDrizle wanted to steal more honey from Felpaw Village... you know, just west of here? You can see it from the cliff...\n\nAnyway... I told him it was a dumb idea but he went anyway, and then the Deadwood tribe got him, and... and...\n\nSniff...\n\nI don't know what they're gonna do! Please find him, <Mr./Ms.> {race}! Even if he is a dummy! I don't want Drizle to get eaten!", completion = "Help! Please help!", objectives = "Find Drizle in Felpaw Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28363] = { id = 28363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirred the Hornet's Nest", description = "Wow!\n\nIt sounds like you really got their attention, {name}. We're never getting in there with them on alert like this.\n\nThere must be a way...\n\nIt's just a matter of time before Schnottz's men activate the obelisk and I need to research the scrolls you found. I need you to figure this one out without me.\n\nSullah has connections in these parts. Maybe he has a solution for getting us inside.", completion = "You know, I believe I have just the thing!", objectives = "Speak to Sullah at Sullah's Sideshow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28364] = { id = 28364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chieftain's Key", description = "Sniff... I'm sorry! I didn't mean to get caught! They grabbed me and put this chain on me and left me here! I can't move and my leg fell asleep and I'm hungry!\n\nThe chief has the key... Chieftain Bloodmaw, the other ones said. He's in the north end of the camp.\n\nBut hurry! Please! Don't leave me alone here!", progress = "Did you get the key?", completion = "Thank you, thank you! I'm getting out of here right away!\n\nAnd if Ferli sent you here... don't tell her I was crying!", objectives = "Retrieve Drizle's Key from Chieftain Bloodmaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28365] = { id = 28365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "<PH>Drizle Safe" }
quests[28366] = { id = 28366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming Bears", description = "I would prefer to do as much as we can to protect my people from the Deadwood tribe without slaughtering every last one of them. We've taken steps towards this before, and if you wish to prove yourself to the Timbermaw tribe, I would ask you do this as well.\n\nLook for the piles of weapons kept in Felpaw Village to the southwest. Take as many as you find. If we disarm the Deadwood tribe, we may be able to stop some bloodshed later.", progress = "Do you have the weapons?", completion = "Thank you, {race}. An action like this will go a long way towards proving yourself as an ally of the Timbermaw.", objectives = "Collect 7 Deadwood Weapons from Felpaw Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28367] = { id = 28367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shroud of the Makers", description = "It is good to have friends, {class}! While kindness is its own reward, there can be tangible benefits too!\n\nSome friends of mine recently intercepted a shipment of Schnottz's plunder and found something that should serve your needs nicely.\n\nIt's a piece of titan technology that renders the user nearly invisible. If you use it in the enemy camp, you might be able to rewire their explosives and make a mess of their operation.\n\nEach charge has a limited duration, so don't stray too far from safety!", completion = "Hah!\n\nI heard it from here! I wish I could've been there to see it!", objectives = "Sabotage 7 Schnottz Powder Kegs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28368] = { id = 28368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire in the Hole!", description = "Land's sakes, pardner! You done shut off those valves but good.\n\nUnfortunately we've had a critical blowout in our gosh-darned central burnoff regulator! Missus Darla's done sent as many workers as she can rustle to go shut it off, but those flames have a mind of their own!\n\nLiterally! They're hoppin' up and grabbin' anyone who comes near! So Darla says if you can muster up out of that cave you're in and beat that elemental, she's got a mighty fine prize in store for ya!", completion = "Well, my entire operation's nearly been ruined. But you came through in the clinch, {name}.\n\nIt could've been worse! I gotta hand it to you.", objectives = "Slay Grolvitar the Everburning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28369] = { id = 28369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Sister, Fanny", description = "Before you go, be sure to stop by the inn behind me. My sister Fanny is inside.\n\nRefugees are pouring into Thundermar from all of the torched Wildhammer settlements around us, and I put Fanny in charge of 'em. She's tough as talons, that one. But she might need your help.", completion = "Me brother sent you? Good! I could use a {class}. Can ya hold yer own in a fight?", objectives = "Talk to Fanny Thundermar at Thundermar in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28370] = { id = 28370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisp-napping", description = "Can you believe these worgen here have wisps?  The night elves showed them all that druid junk and now they've got their precious little wisps too, giving them all the building material they want without having to harm any precious trees.\n\nIf we had those things, we could pull extra wood out of every tree in our site. Free resources, free profit! That's why I've been working on this containment device.\n\nHead to Talonbranch Glade and use it to steal some wisps. Just point and press the button.", completion = "Pretty little things, aren't they? I wonder if we can figure out how to make more of them.", objectives = "Use Darla's Wisp Magnet to collect 5 Talonbranch Wisps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28372] = { id = 28372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Business", description = "All this happy friends stuff is great, isn't it? People working together, healing the forest. But what's gonna happen to the forest when it's healed? It's just gonna sit there?\n\nWe need this lumber. The Horde needs it. I've got orders here to send as many loyal Horde soldiers--and I'm sure you're loyal--up north to Irontree Clearing.\n\nI've already arranged for the hippogryph master to give you a free ride over there. Talk to Darla Drilldozer when you touch down.", completion = "Fez sent you, hmm? At least he's good for something.", objectives = "Take a flight to Irontree Clearing and speak with Darla Drilldozer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28373] = { id = 28373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timbermaw Hold", description = "Okay, I know this is a longshot, but I figure it never hurts to ask.\n\nWhile I deal with the fallout of all the ridiculous nonsense that just went on here, I need you to go speak to some bears. The Timbermaw furbolg control the forests to the northeast, and they're not too fond of us.\n\nI just need someone to give them the idea the Horde isn't all that bad. Head northeast up the road to Timbermaw Hold--don't go into Felpaw Village--and ask the furbolg outside if they have any favors they'd like done.", completion = "We furbolg are not foolish, {name}. We will not yield Timbermaw Hold to any askers.\n\nHowever, we are also in dire need of assistance. If you help us, we will grant you our favor and allow you passage.", objectives = "Speak with Nafien at Timbermaw Hold in Felwood. Timbermaw Hold is to the east, past Felpaw Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28374] = { id = 28374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weeding the Lawn", description = "In a place like this, even something as simple as growing flowers and pulling weeds can require some heroic effort.\n\nThe orchid lashers that grow on all sides of the grove are a sign of healing. But they're not flawless; some of them do succumb to demonic corruption now and then.\n\nI've found the best way to check is to just pull them up. If they're normal, they'll wander around a bit and reroot themselves. If they aren't... well, you'd better be ready for a fight!", completion = "It's hard work, but it's so rewarding when you see them growing up big and strong.\n\nWhen they're not covered with demonic thorns, that is!", objectives = "Pull up 7 Whisperwind Lashers to check them for corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28375] = { id = 28375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Purgation", description = "The time of vengeance has come, {name}. Kasha can once more fly, thanks to you. She will take us to Purgation Isle so that we may confront the Stormpike dwarf general, Vanndar Stormpike, and his captain, Balinda Stonehearth. BOTH will pay for what they have done.\n\nAre you ready? Orkus cannot do this alone.", completion = "This place is dark... foreboding. It smells of piss and fur. There are definitely worgen here and very likely dwarves.", objectives = "Accompany Kingslayer Orkus to Purgation Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28376] = { id = 28376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzerian's Head", description = "The head of one of Deathwing's most formidable black dragons is now in your possession.\n\nWhile many in Azeroth would pay dearly for such an artifact, something tells you that it belongs in a museum for all to see and remember.\n\nHarrison Jones is likely to have the proper connections.\n\nSullah would certainly be happy to deliver it to him.", progress = "You took down that dragon!?\n\nRemarkable!", completion = "Quite an accomplishment, {name}.\n\nI'll be certain that this gets to Harrison when his expedition here is concluded.", objectives = "Take Myzerian's Head to Sullah at Sullah's Sideshow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28377] = { id = 28377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue at Glopgut's Hollow", description = "Well speak of the devil in a blue dress. Fanny's gone and gotten herself kidnapped by ogres!\n\nI don't trust the Thundermars to be able to mount a rescue on their own. I'll round up my gryphon riders and provide some air support.\n\nI'm sure they can use an extra {class} down there, {name}. Grab your gear and look for Colin Thundermar in the Glopgut ogre camp. It's southwest of here, below the cliffs. Hurry now!", completion = "Good to have you fighting at my side again, {name}!\n\nAnd I see the Firebeards have come as well. I suppose they'll provide a distraction while me and my boys do the heavy lifting.", objectives = "Find Colin Thundermar at Glopgut's Hollow in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28378] = { id = 28378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Fanny", description = "We've started tearing this camp apart, {name}, but there's no sign of Fanny. Maybe you can find her.\n\nWe haven't checked the cave just behind me, to the northwest. See if you can find Fanny in the cave!", completion = "Fanny is safe! I hear Firebeard was in there with you? Nice to hear he's finally pulling his weight.\n\nWait, why are you looking at me like that, {name}? Do you know something I don't?", objectives = "Find and rescue Fanny Thundermar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28379] = { id = 28379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Bashin'", description = "Glopgut ogres! I'd say they was dumb as a sack of hammers, but I have more respect for me hammers than that.\n\nWe've fought off their raids for years, but if they're bold enough to steal one of our own, we're gonna have to learn them a lesson.\n\nHelp us smack around some Glopgut ogres! Kill their pounders, hurlers, or bashers either out here or - better - inside the cave. That'll show 'em.", completion = "Har! My men could learn a lot by watching you work. Well done.", objectives = "Kill 10 Glopgut ogres (either Glopgut Pounders, Glopgut Hurlers, or Glopgut Bashers).", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28380] = { id = 28380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pikwik in Peril", description = "What the heck is going on here? Foreman Pikwik should've shut the valves off by now.\n\nWe can cap these leaks all day and if the central valve is off, we're just delaying an enormous explosion.\n\nListen, if you value money, your life, or either combination of the two, you'd better head south to Irontree Cavern and see if you can find Foreman Pikwik.", completion = "It's a disaster down here! The pump's thrown, all my men in there are gone...\n\nYou gotta help!", objectives = "Speak with Foreman Pikwik at Irontree Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28381] = { id = 28381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Denmother", description = "Barely a crow's flight to the north, goblins ravage this forest, clearcutting it to fuel the war machines of the Horde and line their own pockets. This one pays enough pleasant words and crafted lies to the druids here for them to turn a blind eye, afraid to disturb the tenuous neutrality here.\n\nThe worgen of Talonbranch Glade have had enough. Join us! The hippogryph master can take you directly to our home. Denmother Ulrica will welcome any {race} who wishes to fight.", completion = "Welcome to the home of my pack, {class}. Prepare yourself for war.", objectives = "Take a flight to Talonbranch Glade and speak with Denmother Ulrica.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28382] = { id = 28382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy at our Roots", description = "The goblins are already upon us!\n\nWe have tried everything in our power to warn the goblins to leave Irontree Clearing before we resorted to violence. As they turned a blind ear to us, we struck, and now rather than spare the forest they would lay down their lives for greed.\n\nThey will soon know the full extent of our fury! The battle rages just beyond our northern gate. Join our pack in glory and slay any goblin who dares come before us!", completion = "May their blood water our tree. You fight well, {name}.", objectives = "Slay 8 Irontree Choppers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28383] = { id = 28383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisps of the Woods", description = "I have toiled long here with the Denmother to spread the teachings of Cenarius and the ways of the wild. She has gained much of my trust, and in return, I have been allowed to introduce the spirits of the forest to her students. The company of wisps is a great honor, as well as a useful blessing.\n\nBut now the goblins descend on us, and seek to steal the wisps for nefarious use. Please, prevent this blasphemy!\n\nCall the wisps back here from the western woods with this blessed branch, and keep them safe.", progress = "Have the wisps been saved?", completion = "Thank you, {name}. Now the Horde will not be able to defile these poor spirits to aid their brutish ways.", objectives = "Use the Swiftwind Switch to collect 5 Talonbranch Wisps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28384] = { id = 28384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Clearing", description = "Irontree Clearing must be razed. We can afford no mercy if we want to prevent the goblins from spreading their destruction through the entire forest.\n\nAlton Redding, my most trusted protector, has already led much of the pack around the enemy line to strike while they are distracted here. Seek him out to the west, overlooking Irontree Cavern.", completion = "Welcome to the pack, {race}. Let's hope you don't mind getting a bit uncivilized.", objectives = "Speak with Alton Redding near Irontree Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28385] = { id = 28385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oil and Irony", description = "I plan to use the goblin's greed and pollution against them. Any further despoiling of the land they have already carved here will be worth it to stop their further spread.\n\nDeep within Irontree Cavern, just below us, runs many pipes to pump oil through the ground across the entire clearing. These pipes are attached to a master control pump in the very back of the cavern.\n\nEnter the cavern and sabotage the pump. The ensuing havok will give us opportunity for our final strike.", completion = "You flip a few switches on the pump and crank a large handle all the way to the right. There's a shuddering rumble in the nearby walls.", objectives = "Sabotage the Master Control Pump at the bottom of Irontree Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28386] = { id = 28386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Bombs", description = "The workers in Irontree Cavern below us have been driven out already. Something else has overtaken the cave.\n\nThis works in our favor. I spotted at least a few of them dropping explosives as they fled... explosives we'll need for the next part of our plan.\n\nEnter the cave and salvage any abandoned bombs you can find. When you're finished with that and the pump, we'll begin our final assault.", progress = "Was I right? How many did you find?", completion = "Perfect. I've had the pack gather explosives from the rest of the camp as well, and with these, we'll have just enough to get things started once the oil is flowing.", objectives = "Collect 8 Irontree Explosives from Irontree Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28387] = { id = 28387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burnout", description = "Your pump sabotage has caused pipes to break all over camp. The goblins are in a panic over the geysers, and it's about to get worse.\n\nTake the gathered explosives and use them to set the geysers aflame. We're going to do as much damage to the camp as we can, and keep that oil from being used to fuel shredders... or worse, Horde warships.", completion = "Look at them run... the live ones, that is. Glorious.", objectives = "Use the Stolen Irontree Explosives to ignite 7 Oil Geysers in Irontree Clearing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28388] = { id = 28388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Wages", description = "Sad little cowards... look at them flee in panic!\n\nDon't let it fool you, {name}. The second they've regained their wits, those goblins are going to spend every waking moment chopping this forest to bits and sending the pieces to the Horde's war effort.\n\nDon't give them the chance. Kill the workers throughout Irontree Clearing without mercy... show them their greed has a price!", completion = "Serves every last one of them right. Let's hope those in charge send the rest of their greedy scavengers somewhere else.", objectives = "Slay 7 Panicking Workers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28389] = { id = 28389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Denmother", description = "With the goblins scattered and their equipment destroyed, they'll either get the message and leave, or be easy pickings if they choose to stay. We've won here.\n\nYou've fought as fiercely as any member of the pack, {name}. Return to the Denmother and let her know of our success. I'll be maintaining my watch.", completion = "Let the goblins and all the Horde know we will not have offers of peace and sanctuary abused... most of all not in our new home.\n\nI am grateful my people have found allies as bold as you, {name}. This reward will represent your bond with our pack. You will always be welcome here.", objectives = "Speak with Denmother Ulrica at Talonbranch Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28390] = { id = 28390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glop, Son of Glop", description = "Glop had a son. In his grave hubris, he named it Glop. And so the line of fungalmancers continues.\n\nI require you to slay this new fungalmancer. Your shaman ally has already returned, and awaits you at his cave in the southwest of Verlok Stand.", progress = "To this day, I do not understand how filthy stone troggs breed so quickly. Perhaps it is better that it is left that way.", completion = "Perhaps one day, we shall slay these stone troggs more swiftly than they can breed, and in so doing, end the line of fungalmancers forever.\n\nIn time.", objectives = "Speak to Earthmender Norsala, then kill Fungalmancer Glop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28391] = { id = 28391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Brood", description = "Aeosera is restless and stubborn. She scoffs at our dominance, and she needs to be reminded of her place.\n\nI still have the mallet you retrieved for me. Return to the western edge of the Pale Roost and strike the resonating crystal.\n\nI will meet you there and lend what aid I can. Put her back in her place, {class}.", progress = "And so continues the cycle of the stone drakes. Tumultuous wills in stoic frames.", completion = "You are quite skilled at bending the dragon's will, {race}. I would be jealous of your agility, except that it comes with such a fragile frame.", objectives = "Defeat Aeosera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28392] = { id = 28392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Timbermaw Tribe", description = "The Timbermaw furbolg are the last known tribe of uncorrupted furbolg. They huddle on the edge of these lands, ferociously defending their home of Timbermaw Hold.\n\nThough they are proud creatures, they are in need of much assistance. Should you wish to help, follow the road north from here, and seek them out at the entrance to Timbermaw Hold.", completion = "The druids of Talonbranch Glade have assisted us before. We are still unused to \"friendly\" worgen in these woods, but our people are also familiar with the sorrows of curses and corruption...\n\nSorrows that I hope you can aid us in, {class}.", objectives = "Speak with Nafien at the entrance to Timbermaw Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28393] = { id = 28393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dangerous Alliance", description = "SI:7's latest report about Twilight's Hammer and Dark Iron activity worries me, {name}. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We'll be hard-pressed to turn back such a combined force, but if we act before they're ready to strike, we might be able to blunt the attack.\n\nYou must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Do not hesitate to take out the elementals supporting his forces.", progress = "We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", completion = "I'll send these plans to the king and his strategists immediately. If the Dark Irons and their Twilight allies manage to recover and attack, our men will be ready for them. Well done, {name}.", objectives = "Kill 6 Fireguard Destroyers and recover the General's Attack Plans from General Angerforge at the West Garrison in Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28394] = { id = 28394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golem Lord's Creations", description = "The latest SI:7 intelligence on Blackrock Depths is troubling, {name}. It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could prove to be a devastating weapon if used against us.\n\nYou must prevent that from happening, {name}. Find the Manufactory in Blackrock Depths, capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", progress = "We cannot afford to allow those golems to be used against us.", completion = "I know a couple of engineers who will want to take a look at those plans. They won't be using these golems anytime soon. Good work, {name}.", objectives = "Obtain 5 Elemental Modules from the golems in the Manufactory of Blackrock Depths and recover the Elemental Golem Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28395] = { id = 28395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Nafien", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[28396] = { id = 28396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Grazle", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[28397] = { id = 28397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Will Never Expect This...", description = "They made a mistake by not killing me when they had the chance. Perhaps they thought Orkus would drown. HAH! Now they will pay the price for their carelessness.\n\nYou and I will tear this island apart, {name}. They will never expect this! Once all of their soldiers are dead we will confront the leaders. Be on the lookout for attack plans. If we can get our hands on their plans we will be able to put a stop to their whole invasion!\n\nLet's go, {name}!", progress = "We will kill them all!", completion = "Look upon the carnage, {name}. You and I make quite the team!\n\nNow to find those plans and deal with their leaders.", objectives = "Kill 8 Stormpike Dwarves and 8 Bloodfang Sentries on Purgation Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28398] = { id = 28398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pyromancer's Grimoire", description = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain, a magus of renown, plays an important role in leading the Twilight's Hammer forces there. If we could get our hands on his grimoire, I might be able to devise counterspells and other ways of dampening their elemental magics.\n\nYou must descend into Blackrock Depths, locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", progress = "Have you managed to capture the pyromancer's grimoire?", completion = "<The {class} trainer pages through the grimoire quickly.>\n\nI've already seen a dozen spells I never knew existed. This will be most helpful, {name}.", objectives = "Kill 6 Twilight Emissaries and recover Loregrain's Grimoire from Pyromancer Loregrain at the Shrine of Thaurissan in Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28399] = { id = 28399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Binding", description = "I have it on good authority that SI:7 is concerned about collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths. We can act on this information, prove our value to the Alliance, and gain something for ourselves at the same time.\n\nThe report mentions that the Twilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", progress = "Have you managed to find those binding stones?", completion = "The binding stones you brought back are exceedingly powerful. It will likely take me years to learn all their secrets, but I'm certain they'll prove most useful. Thank you, {name}.", objectives = "Recover 6 Elemental Binding Stones from Blackrock Depths. You can find the stones in Shadowforge City, the Domicile, the Shrine of Thaurissan, the East Garrison, and the West Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28400] = { id = 28400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of the Horde!", description = "Now to find their battle plans and take out their leaders! Should we succeed there is an orc high warlord who served in the war in Silverpine that is now stationed at Tarren Mill - located in the heart of Hillsbrad. He will grant both of us commendations for this! We will be heroes of the Horde, {name}!\n\nOnward! Together we will defeat the Alliance filth!", progress = "<High Warlord Cromush looks somber.>", completion = "<High Warlord Cromush salutes.>\n\nHe will be honored as a hero of the Horde, just as he always hoped. What you and Orkus did will save hundreds of lives and ensure that our foothold in Hillsbrad is not lost.", objectives = "Steal the Alliance Battle Plans and Become Heroes of the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28401] = { id = 28401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves of the Firelord", description = "Within the halls of Blackrock Depths, the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros.\n\nIf we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", completion = "You have truly served both the Alliance and your calling as a {class}.", objectives = "Use the Totem of Freedom to free the essences of 6 Fireguards, Fireguard Destroyers, or Blazing Fireguards in Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28402] = { id = 28402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnottz So Fast", description = "I'm nearly ready, {name}.\n\nYour scrolls contained enough information to discern their encryption method. Now all that's left is for me to translate the codes.\n\nI need you to scout out the chamber beneath the Obelisk of the Moon. There are likely to be a few of Schnottz's troops down there that escaped your blast.\n\nYou take care of them and I'll meet you there when I'm finished.", completion = "Alright, {name}.\n\nI think everything is in order. Let's do this!", objectives = "Kill 10 Schnottz Elite Troopers in the Chamber of the Moon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28403] = { id = 28403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Datas", description = "There should be two titan communication devices in this chamber.\n\nIf my translations are correct, one is a death trap and the other will accept the codes and activate the obelisk.\n\nLet's hope I get this right.\n\nLet me know when you're ready.", completion = "Okay, {name}.\n\nI think I can do this manually, but I'll need your help.", objectives = "Accompany Harrison Jones in the Chamber of the Moon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28404] = { id = 28404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Do It By Hand", description = "Yes, this all looks familiar enough.\n\nThanks to all the information you gathered for me, I'm sure that I can activate the mechanism. I'll just need some time free from distraction.\n\nAs soon as I get started, you can count on that titan construct to try and stop me.\n\nThat's where you come in.\n\nI don't need to remind you of what's riding on this. Take down that guardian!", progress = "Almost got it...", completion = "That should do it.\n\nStand back!", objectives = "Defeat the Titanic Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28405] = { id = 28405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now SI:7 sends word that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the knowledge of the cult, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", completion = "Thanks to your efforts, those weapons will never shed Alliance blood. Excellent work, {name}.", objectives = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths, then break them over the Black Anvil in Shadowforge City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28406] = { id = 28406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Army", description = "Things are getting interesting in Blackrock Mountain, {name}. Our sources report that the Dark Iron dwarves have formed closer ties with Twilight's Hammer and both are preparing for a major offensive.\n\nI've made the contents of the report known to key leaders in Stormwind and I want you to help deal with this emerging Dark Iron threat.\n\nThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths. Take this poison and apply it to their grain reserves.", completion = "With any luck, the poison will take out a fair number of their frontline troops before they know what's happening. That should stall them for the near future. SI:7 is most pleased with your work.", objectives = "Use the Fast-Acting Poison to contaminate 6 Grain Rations in the West Garrison or East Garrison of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28407] = { id = 28407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bachelorette", description = "Firebeard? Marry my sister!? I swear the world's gone mad, {name}!\n\nStill, maybe Kurdran is right. A nice normal wedding would ease everyone's mind... and maybe cool off Firebeard a little. It was great to actually work together here against the ogres.\n\nRight then! It's all up to Fanny. Something tells me she won't want to be tied down.\n\nFly back to Kirthaven and see if she's game. I'll finish up the nasty business with the ogres here.", completion = "<Fanny throws her arms up, exasperated.>\n\nYou, Kurdran, Firebeard, and now my brother - everyone's got wedding fever!\n\nFine, fine, I'll marry Keegan Firebeard. But only 'cuz he's strong and handsome, with a jaw that can cut gravel and an arse like an anvil. Not for any political reasons.\n\nWe're going to need your help, though. We got a whole lotta wedding to put together, and not a lot of time to do it.", objectives = "Talk to Fanny at Kirthaven in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28408] = { id = 28408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Bold", description = "By tradition, Wildhammer brides wear white to show their purity. In addition, they wear a crown of black feathers - to show their CHUTZPAH.\n\nOwl feathers make the boldest statement, and Fanny deserves nothing less. Tawny owls are native to the Highlands. Look for them circling near trees that grow along the cliffs, and take their feathers.\n\nYou'll probably want to kill 'em, first.", progress = "Have you Fanny's feathers?", completion = "Ah, you work fast. Bold feathers for a bold woman. Well done!", objectives = "Collect 12 Pristine Owl Feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28409] = { id = 28409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Brewed", description = "It would be an insult to celebrate a Wildhammer wedding without drink. Kurdran himself called for a few kegs of rare Thunderbrew Lager to be sent ashore from Highbank, but the caravan can't get through the pass.\n\nFollow the road east of here, around the south side of Thunderstrike Mountain, and catch up with the caravan. Look for a fellow named Hammelhand, and help him get the booze through the pass!", completion = "Ahh, Russell the Bard is always raving about Thundermar Lager. I guess it doesn't have the kick of a good Wildhammer brew, but he goes on and on about the \"body\" or \"flavor.\" I guess we'll find out, eh?", objectives = "Speak with Hammelhand on the road East of Kirthaven, and escort a supply caravan back to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28410] = { id = 28410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stolen", description = "Everyone's going to want to dress their best for this, and finery is in short supply in the Highlands.\n\nI understand that those goblin wretches off the coast use the finest silk for repairing their zeppelin air envelopes. A waste!\n\nFind a zeppelin flying back and forth between Dragonmaw Port and the Krazzworks, and liberate some silk from the cargo hold in the lower decks.", progress = "How did the air raid go?", completion = "Oh, aye! Kilts for the gents, gowns for the bridesmaids.\n\nJust don't tell the ladies they're wearing clothes fit for a blimp.", objectives = "Collect a bolt of Fine Dark Cloth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28411] = { id = 28411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stewed", description = "Finally, we're going to need a feast. And none of that \"finger food\" stuff! This crowd wants meat, and lots of it.\n\nGather up venison from Highland elk and does. Highland worg are good eatin' too - bring back some ribs. We'll show you a feast like you've never had in all the Eastern Kingdoms, friend.", progress = "What's the food situation, {name}?", completion = "Lookat that! You're practically bent double under the weight of all that meat. I'd better get my people cooking.", objectives = "Gather 8 slabs of Fresh Venison and 5 Worg Ribs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28412] = { id = 28412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of the Family" }
quests[28413] = { id = 28413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words and Music By...", description = "I've written many an epic tune in my lifetime, {name}, but this upcoming wedding deserves a very special ballad. And fast!\n\nShould I write a love song? A lighthearted ditty? A bawdy drinking song?\n\nI could use some help with the lyrics, if you fancy a go at it.\n\nTalk to me and we'll write a song together!", completion = "Well, it's catchy, that's for sure.\n\nBut is it a classic?", objectives = "Talk to Russell Brower and help him write a song.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28414] = { id = 28414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fourth and Goal", description = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal.\n\n<The coach leans in close and whispers in your ear.>\n\nNow, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal!\n\nI've modified the footbomb to give you the extra power that you'll need.\n\nNow get out there and make me proud!", completion = "Uh... you did it, kid. You REALLY did it! We won the game and....\n\nDID YOU SEE THAT DRAGON?!!!", objectives = "Get in the Bilgewater Buccaneer and score the winning goal by kicking the Footbomb through the smokestacks behind the opposing goal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28415] = { id = 28415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SEVEN! YUP!", description = "We have to take action.  Winky and Gor'tesh were fighting, so I planned this friendship ceremony to help the two of them make up.  Everything was going well, until...\n\nWell, you know the rest.\n\nI even bought drinks!\n\nWinky loves flameflies.  He runs off to chase them most every night.  I'm thinking maybe that's where he went.\n\nYou'll find flameflies to the west and north, wherever you find lava.  Bring me seven of them, and hurry!\n\nGor'tesh might leave next!", progress = "<Oralius grasps at the air, lifts his fist, and peers hopefully between his clenched fingers.>", completion = "You'll never guess what happened!  Winky came back!  No flameflies needed.\n\nCan a dwarf get a celebratory belly rub?  Come on now!  RUBBA MAH BELLY!", objectives = "Gather 7 Flameflies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28416] = { id = 28416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Vengeance", description = "{name}... is that you?  I thought you were dead, with the rest of them!\n\nNo, you were always strong, even back then, even in Redridge.\n\nOur fight's not over, {name}.  They already attacked our homeland once.  I'm here to make sure it doesn't happen again.\n\nIf you can still fight like you did back in the day, then join me.  You can start by heading south, to the Whelping Downs, and slaying their whelpers and their hatchling black dragons.\n\nIt'll be like old times.", completion = "Glad to have you on my side, {name}.  Bravo Company reunited, right?\n\nOh, did I mention that Troteman's here, too?", objectives = "Slay 5 Blackrock Whelpers and 5 Flamescale Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28417] = { id = 28417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Done Nothing Wrong", description = "The Blackrock orcs of the steppes serve a dark master -  one who performs twisted experiments on living creatures to create his own menagerie of abominations.  Many of his test subjects are as corrupted as their master, but others are completely innocent.\n\nIn the whelping downs to the south, they chain baby dragons to the ground, preparing them for such experiments.  I will not stand for this.  Break their fetters and return the hatchlings to me... to safety.", progress = "I hope we weren't too late.", completion = "I will see to it that these dragons are taken care of.", objectives = "Obtain a Freed Red Whelpling, a Freed Green Whelpling, a Freed Blue Whelpling, and a Freed Bronze Whelpling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28418] = { id = 28418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Vengeance", description = "I am a Blackrock orc by birth.  I spent a large part of my youth inside that mountain.\n\n<Ariok motions towards Blackrock Mountain, to the north.>\n\nBut while I share blood with them, I do not share their outlook.  And I am seeking an ally to assist me in stopping their upcoming attack.\n\nSo prove yourself.  Travel south, to the Whelping Downs, and slay their whelpers and the hatchling black dragons.  Prove to me that you're ready for this war.", progress = "I suppose you don't have what it takes.\n\nThat's fine.  I can fight this war myself.", completion = "So you're in, then?\n\nGood.", objectives = "Slay 5 Blackrock Whelpers and 5 Flamescale Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28419] = { id = 28419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up", description = "If we're going to wage war against the Blackrock clan, we're going to need to plan ahead.  My father has already put the plan together - now it's time to execute.\n\nI need scorpid stingers... the sharpest ones you can find.  Scorpids are all over the steppes, but you can find most of them in the gulch to the west.\n\nDon't worry about what they're for.  You'll find out soon enough.", progress = "Back already?", completion = "Those scorpids are easy to underestimate.  You're lucky you didn't end up on the end of one of these barbs.  Or maybe you're just good.\n\nI'll add these to the stockpile.  We're not done yet, {race}.", objectives = "Obtain 5 Razor-Sharp Scorpid Barbs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28420] = { id = 28420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Future Project", description = "According to my father, we'll need worg hides, and lots of them.  It doesn't matter if they're torn, burned, or bloody, but we need plenty of them.\n\nActually, it's probably better if they're a little beat-up.\n\nYou'll find worgs both to the west and to the east of here.", progress = "Let's take a look at those hides.", completion = "Believe me, {name}... I'm just as anxious to get to the killing as you are.  We've got to keep to the plan.  The armageddon will come soon enough.\n\nI'll keep these hides here.", objectives = "Obtain 11 Ember Worg Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28421] = { id = 28421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mud Hunter", description = "Hope you're not afraid of getting dirty.  Judging by the looks of you, that won't be a problem.\n\nTo the north, at the lava's edge, you'll find piles of dark mud.  I need it.\n\nIt'd be best if you didn't ask questions, and focused your efforts on following orders, {name}.", progress = "You'll want to watch out for those obsidian elementals.  They have a tendency to sneak up on you.", completion = "This is exactly what we need.\n\nDon't worry, {name}... the killing will come soon enough.", objectives = "Obtain 9 piles of Obsidian-Flecked Mud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28422] = { id = 28422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sand, the Cider, and the Orb", description = "My father is waiting for us to the east.  Before we head out though, we need to gather some more supplies.  This time, you'll be taking it from a warlock by the name of Gorzeeki Wildeyes.\n\nYou'll probably find him to the northwest, near the Altar of Storms.  Tell him he's going to help us out.  We need the sand, the cider, and the orb.\n\nHe'll know what it means.", completion = "Gah!  Who are you?\n\nOh, so Ariok sent you?  Good.  Would ya mind sticking around for a while?  It's nothing big... I just need you to kill some warlocks for me.", objectives = "Speak with Gorzeeki Wildeyes near the Altar of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28423] = { id = 28423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlocks Have the Neatest Stuff", description = "Ariok said he needs supplies?  I've got plenty of supplies!  Problem is, those warlocks have kicked me out of my home, and they're not letting me back in.\n\n<Gorzeeki sizes you up.>\n\nYou might be able to get in, though.  Head north, and grab some of my slumber sand, my fel slider cider, and a clear glass orb.  I'm pretty sure that's what he wants.\n\nOh, and if you happen to accidentally kill any of those orcs while you're up there, I wouldn't be terribly upset.", progress = "Let's see if you managed to get everything.", completion = "I hope that's what Ariok was looking for.  It's not doing me much good right now, anyhow.", objectives = "Obtain a handful of Slumber Sand, a jug of Fel Slider Cider, and a Clear Glass Orb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28424] = { id = 28424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Boxing", description = "Ner'gosh the Shadow is the leader of those warlocks to our north.  He's the jerk that kicked me out of my home once those Blackrock orcs started showing up.  Well, they're all jerks, but he's the jerkiest.\n\nIf I'm ever going to move back in near the Altar, Ner'gosh has to go.", completion = "Knowing the way those orcs operate, there'll be another one to take his place soon.  I'll see if I can't sneak back into the altar before that happens.\n\nThanks, buddy.", objectives = "Slay Ner'gosh the Shadow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28425] = { id = 28425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Ariok", description = "Well I suppose I'm done with you here.  I'll go shoo those other warlocks out when I build up the courage.\n\nHere, don't forget those supplies.", progress = "It looks like you managed to deal with Gorzeeki.", completion = "<Ariok looks through the crate.>\n\nGood, good, good.  We can move on.  Our war takes us east, away from Blackrock Mountain... for now.", objectives = "Bring the Warlock's Supplies back to Ariok at Flamestar Post in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28426] = { id = 28426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiselgrip, the Heart of the Steppes", description = "We're headed to Chiselgrip, right in the center of these steppes.  We'll rendezvous with the Thorium Brotherhood there, as well as with my father.\n\nAre you familiar with the Brotherhood?  Those dark iron dwarves have helped me out more than once.  We may need their help again.\n\nWe'll pass through Black Tooth Hovel on our way there.  What do you say we kill a few of the Blackrock while we travel?  I'm getting a little restless here in this camp.", completion = "You'll have to excuse me, but we're not taking visitors right now.  I'll ask you to leave Chiselgrip out the same door you came in.\n\nOh, Ariok... is that you?", objectives = "Kill any 15 Blackrock troops on your way to Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28427] = { id = 28427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Needle in a Hellhole", description = "Lok'tar, {class}.  My name is Eitrigg, of the Argent Crusade... formerly of the Warchief's Honor Guard.  Before that, of the Blackrock orcs.\n\nI trust my son has briefed you on our plan.  He hasn't?  That is probably for the better.\n\nThe next part of the plan is going to require a bit of subtlety.  Speak with Thelaron Direneedle, the tailor here in town.  I've already given him the hides and mud that you've collected.  He's going to need to size you.\n\nThat's right, {race}: you're going undercover.", completion = "You need a disguise?  Well, you came to the right place, honey.\n\nLet me take a look... mm-hmm.  I know exactly what we'll do.", objectives = "Speak with Thelaron Direneedle at Chiselgrip in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28428] = { id = 28428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an orc.  Their army is made mostly of orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28429] = { id = 28429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an ogre.  The firegut ogres have always worked for the Blackrocks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28430] = { id = 28430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a goblin.  The Blackrocks have been known to hire goblin mercenaries to fill their ranks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28431] = { id = 28431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a troll.  The Smolderthorn trolls have always worked with the Blackrock orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", objectives = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28432] = { id = 28432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Black Tooth Hovel", description = "Undercover work is all about swagger.  Just act like you're supposed to be there, and you'll be fine.\n\nYour contact inside Black Tooth Hovel will be an orc by the name of Quartermaster Kaoshin.  He does NOT know you're a spy, so try and stay cool.  Do whatever he asks of you.\n\n<Eitrigg presses a small mechanical object into your palm.>\n\nPlace this device in your ear.  I will be in touch to give you any special instructions.\n\nGood luck out there, soldier.", completion = "Where have you been, grunt?  You're late!  Give me one reason why I shouldn't kill you on the spot!", objectives = "Speak with Quartermaster Kaoshin at the Black Tooth Hovel in Burning Steppes.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28433] = { id = 28433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grunt Work", description = "Bah!  You're lucky I'm short-handed today.  Otherwise I'd make you my personal whipping <boy/girl> for the week.\n\nThe officers and high-ranking soldiers need their boots polished.  They've left them out in front of their huts.\n\nI want to see my reflection in those boots, grunt!  Get to work!", completion = "Hmph.  Good work, grunt.", objectives = "Vigorously polish 7 pairs of Blackrock Boots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28434] = { id = 28434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Cuts", description = "<You hear a buzzing in your ear.>\n\n{name}?  It's Eitrigg.\n\nWe've just received the final bit of information for your next mission.  There are three marks that we'd like you to take down.  The first is Voodooist Timan, whom you'll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.\n\nYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.", completion = "Not only did you pull off the executions, you managed to make them all look like accidents.\n\nYou were the right {race} for this undercover work.  Good job, soldier.", objectives = "Use the Razor-Sharp Scorpid Barb on Voodooist Timan atop the Pillar of Ash, Worgmistress Othana in the worg pens, and Gorlop when he is near the lava pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28435] = { id = 28435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kodocaller's Horn", description = "Alright, I've got some actual, legitimate, important work for you.  We've got to call the kodos in from the grazing lands to the south.  General Thorg'izog says we'll be moving out into Redridge soon, and I won't be caught with my kodos down.\n\nUse this horn near a kodo.  It will return to the camp when it hears the call.\n\nYou'll want to watch out.  Sometimes the kodos get a little feisty, so you need to knock them around a bit before they listen to you.", objectives = "Use the Horn of the Callers to call 7 Blackrock War Kodos back to camp. If a kodo turns hostile, fight it until it submits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28436] = { id = 28436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Horn For Ourselves", description = "{name}, it's Eitrigg.  I want you to hold onto that horn.  I'm sure we can improvise and find a way to work it into the plan.\n\nI'm more than a little concerned about what Kaoshin said about attacking Redridge.  We knew an attack was imminent, but not this soon!\n\nReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You're not done with your undercover work yet.", progress = "Welcome back, soldier.", completion = "True, an attack on Redridge is an attack against the Alliance... but it is also an attack against innocents.\n\nI won't stand for that.  Not as a Crusader.  Not as an orc.\n\nIt's time we taught the Blackrock clan - my old clan - that their raiding days are over.", objectives = "Bring the Horn of the Callers back to Eitrigg at Chiselgrip in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28437] = { id = 28437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Thorg'izog", description = "Kaoshin turned out to be more helpful than I expected, but we're done with him.  It's time you spoke with the General.  I think you're ready.\n\nGeneral Thorg'izog is one of the \"Big Three\" that run the Blackrock forces here in Burning Steppes.  He leads from the Blackrock Stronghold to the northwest.  Put on your disguise and go speak with him.  See if you can earn his trust.  I will be in touch, should I need anything further.", completion = "More outsiders?  What do you want?", objectives = "Speak with General Thorg'izog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28438] = { id = 28438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial by Magma", description = "I suppose I'll make the most of this situation.  These goblin mercenaries brought this enormous fire elemental to my stronghold as a \"thank you\" for hiring them.  What am I going to do with an elemental here in the steppes?  That's like bringing sand to the beach.\n\nIf you're looking for work, then prove yourself.  Talk to this goblin here, and challenge his elemental to a fight.  The victor earns my respect, and my time.", progress = "What's the matter, are you scared?", completion = "I had a feeling you'd be the one returning to me.  I like your style, soldier.", objectives = "Speak with Wyrtle Spreelthonket and ask him to release Magma Lord Kolob. Then defeat Magma Lord Kolob in battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28439] = { id = 28439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Law and I Am the Lash", description = "I've been looking for a good, strong soldier like you.  I need someone to keep my troops in line.\n\nOutside the stronghold, you will find orcs, ogres, and trolls preparing for the assault on Redridge.  My sergeants keep them in line, but I'd like you to assist them.\n\nTake this cudgel and discipline a few of my soldiers.  I don't care if they're misbehaving or standing perfectly in line, I want them beaten.  I want them focused, battle-hardened, and obedient.\n\nNow go.", completion = "I have a feeling we'll be hearing about you and your exploits for a long time, soldier.  I look forward to fighting by your side in Redridge.\n\nYou are dismissed.", objectives = "Use the Blackrock Cudgel of Discipline on 20 troops in the Fields of Honor. If one of the troops discovers your disguise, cudgel him to death before he can unmask you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28440] = { id = 28440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abuse of Power", description = "{name}?  Eitrigg here.\n\nIt sounds like you have earned Thorg'izog's trust, and he's assigned you to discipline duty.  This is fortunate.\n\nWe need you to take out his sergeants.  You'll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You'll have to act fast, because if they realize you're not one of them, they can unmask you.  Strike quickly and ferociously, {name}.", completion = "Without those sergeants, Thorg'izog will be hard-pressed getting his troops ready for battle.\n\nAlready the dominoes are beginning to fall, {name}.", objectives = "Kill 5 Blackrock Sergeants using the Blackrock Cudgel of Discipline. Defeat them quickly, before they have a chance to unmask you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28441] = { id = 28441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough Damage For One Day", description = "We do not have any further strategic need for Thorg'izog or the Blackrock ground troops.  We must continue to the next phase of the plan.\n\nWhen you are finished at the stronghold, return to my son and me, here in Chiselgrip.", completion = "Are you alright?\n\nGood.  You were strong out there, {name}.  Strong, and wise.\n\nNow pack up your things.  We're moving out of here.", objectives = "Return to Eitrigg at Chiselgrip.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28442] = { id = 28442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame Crest", description = "Our work here in Chiselgrip is done, mostly thanks to you.  We'll now be moving on to the northeast, to Flame Crest.\n\nFlame Crest is in the cliffs, past the Ruins of Thaurissan.  It should serve as a sufficient base of operations for the final stages of our plan.\n\nOf course, my son Ariok will be joining you on the road.  As will I.", completion = "Oh.  Visitors?", objectives = "Report to Kibler at Flame Crest in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28443] = { id = 28443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackened Ashes", description = "I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we're going to do this, we're going to do it right, and that means being prepared.\n\nI need ash, {name}.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the southeast.  The stuff is deep, deep black, which is what we need for our next disguise.\n\nDon't worry, you've already got a disguise.  This one is for someone... well, someTHING... else.", progress = "The ashes of the obsidian elementals are particularly dark - exactly what we need for our purposes.", completion = "Yes, these will do.  I will get this packed up for you.", objectives = "Obtain 9 piles of Obsidian Ash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28444] = { id = 28444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Demons of the Land", description = "The lava beds nearby - to the south - play host to flamekin, a brand of fire demon that has long roamed the steppes.  Situations are such in the Blackrock army that, if we are careful, we may be able to sneak some of these flamekin behind enemy lines to cause some havoc.\n\nBring me the bodies of several flamekin.  As demons, they are easily resurrected, and then we can use them for our own purposes.", progress = "The flamekin are weak, but they travel in packs.  Be cautious.", completion = "To the untrained eye, these will look exactly like imps.\n\nWe just need to get them to that untrained eye.  I'll work on preparing them for delivery.", objectives = "Obtain 18 Fallen Flamekin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28445] = { id = 28445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heap of Delicious Worg", description = "We're going to need fresh meat, which means you're going to be hunting worg.  The worg on this side of the steppes should be your target.\n\n<Eitrigg produces a large blade, which he hands to you.>\n\nHunt the giant ember worgs.  Once you've killed them, use this saw to remove the choicest bits of meat from their bodies.  You will find these worgs all over the steppes, but the closest pack rules the land just to our southeast.", progress = "Any luck out there?", completion = "This meat looks good... but I think it needs a little \"seasoning\".  I'll make sure that gets taken care of.\n\nThank you, {name}.", objectives = "Use the Worgsaw on the bodies of slain Giant Ember Worgs to obtain 40 Worg Cutlets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28446] = { id = 28446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Tour", description = "My legs are getting a little restless again.  You interested in taking a little tour, {name}?\n\nWe're going to take a trip around Dreadmaul Rock.  I'd like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we're on the way.", completion = "<Ariok is covered in blood and sweat.>\n\nThat was exactly what I needed.", objectives = "Kill 25 Black Dragonspawn or Black Wyrmkin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28447] = { id = 28447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Vanguard", description = "The Blackrock orcs don't come alone.  You've already seen that they've got the Firegut ogres and Smolderthorn trolls on their side.  Unfortunately for us, they're also teamed up with the black dragonflight.\n\nThe orcs and the dragons have already sent some of their champions to stand guard at rally points, which are marked by a dragon skull on a pike.  You and I are going to find these rally points and take out this vanguard before the battle starts.\n\nReady?", progress = "Come on, {name}, there's still more of them left.  Our job isn't done.", completion = "Your kill count is adding up, {name}.  We're chipping away at them.\n\nAnd we are going to win.", objectives = "Slay Minyoth, Whelptamer Akumi, Terromath the Seared, and Tugnar Goremaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28448] = { id = 28448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deal With a Dragon", description = "While we are circling around Dreadmaul Rock, there's one more stop that we need to make.\n\nYou remember the hatchlings that you freed from the Whelping Downs?  I've been watching over them, and now we're going to deliver them to someone who will take care of them better than we can.  He's staying in Slither Rock, to the northeast of Dreadmaul Rock.\n\nHis name is Acride, and he might be the key to victory in the upcoming battle.", progress = "You've arrived, {name}.", completion = "Yes, the whelplings.  I will take care of them.\n\nAs for the agreement I made with your father earlier, tell him that I will hold up my end of the bargain.  You will have your dragon for the battle against the orcs.\n\nWe share your grudge against the Blackrock clan.", objectives = "Deliver the Rescued Whelplings to Acride at Slither Rock in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28449] = { id = 28449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placing the Pawns", description = "<You hear a buzzing in your ear.>\n\n{name}.  It sounds like you and Ariok have finished with your tasks.  I've also finished mine.\n\nReturn to Flame Crest.  I've prepared a few packages to deliver to the Big Three: Thorg'izog, Neeralak, and Xi'lun.  You've already met General Thorg'izog.  This will be your chance to meet the other two.\n\nThat is, before you kill them.", completion = "Good, you're back.\n\nI hope you've still got that disguise.  You're going back undercover, {name}.", objectives = "Return to Eitrigg at Flame Crest in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28450] = { id = 28450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Thorg'izog", description = "General Thorg'izog is staying among the ogres in the Firegut Furnace, a cave on the western edge of Dreadmaul Rock.  I'd like you to deliver this to him and the ogres.\n\nInside this package, you will find the worg cutlets you obtained, marinated in the fel slider cider that we took from the Altar of Storms.\n\nI would avoid eating it if I were you.\n\nBring it to General Thorg'izog.  He will make sure that his troops are fed and, with any luck, he will eat some himself.", progress = "What've you got there, soldier?", completion = "Well would you look at that!  My favorite soldier comes through in the clutch!\n\nI'll make sure to get this distributed among the ogres.\n\nI'll see you in Redridge, soldier.  For the glory of the Blackrock!", objectives = "Using your Blackrock Disguise, bring the Slider Cider-Marinated Cutlets to General Thorg'izog at Firegut Furnace in Burning Steppes. Speak with Eitrigg if you need a new Blackrock Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28451] = { id = 28451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Neeralak", description = "The warlocks of the Blackrock Clan often practice their magic in the Skull Warren, a cave on the eastern side of Dreadmaul Rock.  Their leader, Xi'lun, is busy elsewhere, so the cave is currently being held by another of the Big Three: Dragon-Lord Neeralak.  And Neeralak's expertise is in dragons, not in necromancy.\n\nI've used the slumber sand on those flamekin you captured.  Try to convince Neeralak that they're warlock imps, and not flamekin.  When they wake up, they won't be happy.", progress = "What?", completion = "What are these?  Oh, are these imps?\n\nI'm pretty sure that imps don't just fall asleep in boxes!\n\nI'll take your word for it, though.  I don't understand any of this warlock crap.  Leave them in the corner.", objectives = "Using your Blackrock Disguise, sneak into the Skull Warren and convince Dragon-Lord Neeralak to take your Crate of Sleeping Flamekin. Speak with Eitrigg if you need a new Blackrock Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28452] = { id = 28452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Xi'lun", description = "Intel tells us that High Warlock Xi'lun - the final member of the Big Three - is within the cave atop Dreadmaul Peak, preparing for his big moment.\n\nHe is waiting for a delivery: an Orb of Domination, with which he can perform a powerful summoning ritual.  I want you to give him this:\n\n<Eitrigg hands you a glass orb.>\n\nThis is the clear glass orb that you freed from the Altar of Storms.  It is powerless.  Give it to Xi'lun, and cross your fingers that he doesn't notice.", progress = "I don't have time for games, fool.  Get out of my sight.", completion = "Pff!  You're late!  Do you know how long I've been waiting for Ner'gosh to deliver this orb?\n\n<Xi'lun looks down at the orb, then up at you.>\n\nThere's something strange about this orb... it's too...\n\n<Xi'lun trails off.>\n\nNever mind, it must be my nerves talking.  Thank you for the delivery.  For blood and honor!", objectives = "While using the Blackrock Disguise, deliver the Clear Glass Orb to High Warlock Xi'lun atop Dreadmaul Rock in Burning Steppes. Speak with Eitrigg if you need a new Blackrock Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28453] = { id = 28453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locked and Loaded", description = "{name}, come in.  Can you read me?\n\nThe battle is about to start.  I hope you've delivered all of those packages.\n\nI need you here in Flame Crest, NOW.", completion = "{name}'s here!  We can get started.\n\nThis is our big moment, {name}.  I hope you are prepared.", objectives = "Report to Eitrigg at Flame Crest in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28454] = { id = 28454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Dreadmaul Rock", description = "This is it, {name}.  A sad day... but a day in which the Blackrock orcs will learn a powerful lesson.  Today, our plan comes to fruition.\n\nCome with me.  We're going to go talk to Acride and call in that favor that he owes us.  Then we'll stop this invasion of Redridge before it even starts.", progress = "Now's our chance!  Crush them!  We won't get another opportunity like this!", completion = "<Eitrigg looks over the devastation below.>\n\nOur job is almost done, {name}.  It's time to deliver the deathblow.", objectives = "Slay 200 Blackrock Invaders. If you should lose your vehicle, use the Horn of the Callers to summon it again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28455] = { id = 28455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glory Amidst Chaos", description = "You and my son are going back to that mountain.  There's three orcs who survived the attack, and we won't rest until they're dead.\n\nThat's right, I'm talking about the Big Three.\n\nGeneral Thorg'izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain's peak.  Xi'lun is in the back of the Skull Warren, plotting with his fellow warlocks.\n\nLeave your mark, {name}.  Topple these corrupt Blackrock orcs once and for all.", progress = "Good luck, brother.", completion = "<Eitrigg bows.>\n\nWelcome home, boys.", objectives = "Kill General Thorg'izog, Dragon-Lord Neeralak, and High Warlock Xi'lun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28456] = { id = 28456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spoils of War", description = "While the Blackrock orcs still swarm in their spire, I doubt their plans will take them anywhere near the innocent people of Redridge anytime soon.  You and Ariok saw to that.\n\nI'd say we were fairly resourceful here in Burning Steppes - those warlock supplies we collected certainly came in handy, as did the obsidian ash that we used to conceal our dragon.\n\nThere were, however, some collected items left over.  Please, take your pick before you move on, beyond the steppes.", completion = "You peer inside, and find...", objectives = "Inspect the Box of Left Over Supplies at Flame Crest in Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28457] = { id = 28457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dangerous Alliance", description = "The Shattered Hand believes that the Dark Iron dwarves and Twilight's Hammer are working together. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We can't allow such a force to depart Blackrock Mountain.\n\nYou must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Eliminate the elementals Twilight's Hammer has provided to support his forces.", progress = "We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", completion = "The warchief will be most interested in seeing these plans. You are a most loyal member of the Horde.", objectives = "Kill 6 Fireguard Destroyers and recover the General's Attack Plans from General Angerforge at the West Garrison in Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28458] = { id = 28458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pyromancer's Grimoire", description = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain is a powerful and influential magus in the Twilight's Hammer delegation. If we could get our hands on his grimoire, I could develop counters for Twilight's Hammer spells and curses.\n\nYou must descend into Blackrock Depths, locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", progress = "Have you managed to capture the pyromancer's grimoire?", completion = "<Ureda looks through the grimoire with interest.>\n\nThere's a wealth of arcane knowledge in this book! We will learn much about our enemies and the arcane arts.", objectives = "Kill 6 Twilight Emissaries and recover Loregrain's Grimoire from Pyromancer Loregrain at the Shrine of Thaurissan in Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28459] = { id = 28459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Binding", description = "The Shattered Hand has discovered increased collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths. We have an opportunity to strike at our enemies and empower ourselves, {name}.\n\nTwilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", progress = "Have you managed to find those binding stones?", completion = "The binding stones you brought back are exceedingly powerful. Not only have we dealt a blow to the Horde's enemies, but you have also discovered a fascinating source of power.", objectives = "Recover 6 Elemental Binding Stones from Blackrock Depths. You can find the stones in Shadowforge City, the Domicile, the Shrine of Thaurissan, the East Garrison, and the West Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28460] = { id = 28460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat of the Winterfall", description = "I came to Winterspring to investigate the Frostfire Hot Springs. I've noticed that the water seems to have... strange qualities. I haven't yet been able to discover the source, and to tell you the truth, I've had some difficulty lately, due to the Winterfall furbolg.\n\nThey seem to be drawn to the springs, just as I am. They have become extremely protective of the water, and won't let me come near the two larger springs to the north of here.\n\nI'd like to continue my studies, so won't you help me?", completion = "Thanks so much, {name}! Now I can get back to work here.\n\nDid you find anything of interest at the Winterfall camp?", objectives = "Slay 15 Winterfall furbolg of any kind near the Frostfire Hot Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28461] = { id = 28461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golem Lord's Creations", description = "The Shattered Hand has discovered some disturbing information in Blackrock Depths. It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could be a great advantage for our enemies.\n\nIt is your duty to prevent that from happening. Find the Manufactory in Blackrock Depths, capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", progress = "We cannot afford to allow those golems to be used against us.", completion = "Can you imagine what would happen if they got these models working and into the field? You've done a great service for the Horde, {name}.", objectives = "Obtain 5 Elemental Modules from the golems in the Manufactory of Blackrock Depths and recover the Elemental Golem Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28462] = { id = 28462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Firewater", description = "This vial that you picked up from the Winterfall furbolg is empty, but you can detect a few drops of a strange green liquid inside; it almost glows.\n\nIs it something important?\n\nDonova Snowden would probably be able to tell you more, since she has been camped by the hot springs in Winterspring for some time now.", objectives = "Bring the Empty Firewater Flask to Donova Snowden in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28463] = { id = 28463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Army", description = "As a member of the Shattered Hand, you know that it is our job to watch the Horde's enemies. We have discovered that the Dark Iron dwarves and their new allies, Twilight's Hammer, are preparing to attack.\n\nI'm sending you to help deal with this threat before the Dark Iron army marches. Take this poison and apply it to the soldiers' rations of grain in Blackrock Depths.\n\nThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths.", completion = "The poison should decimate their ranks if they're slow in discovering the tainted rations. Even if it does not kill most of the troops, we will have delayed them significantly. Well done.", objectives = "Use the Fast-Acting Poison to contaminate 6 Grain Rations in the West Garrison or East Garrison of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28464] = { id = 28464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling to Corruption", description = "The aggression of the Winterfall furbolg has to have its source somewhere. I'd like to get to the bottom of it if I can!\n\nI've seen the furbolg in the camps to the north brewing something in a cauldron. They seemed very protective of it... if whatever they're cooking up is what's causing this, I must examine it myself.\n\nFind that cauldron if it's still there, and bring me back what's inside!", completion = "Inside the cauldron bubbles a rotting, repulsive-smelling substance...", objectives = "Find the Winterfall Cauldron at the northern Winterfall camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28465] = { id = 28465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves of the Firelord", description = "Within the halls of Blackrock Depths, the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros.\n\nIf we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", completion = "Your actions honor the ancestors and the Horde, {name}.", objectives = "Use the Totem of Freedom to free the essences of 6 Fireguards, Fireguard Destroyers, or Blazing Fireguards in Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28466] = { id = 28466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", completion = "Without those weapons, the Dark Irons will never be a match for the Horde. You have served your brothers and sisters well this day, {name}.", objectives = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths, then break them over the Black Anvil in Shadowforge City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28467] = { id = 28467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Goo", description = "The greenish substance inside the cauldron is putrid and viscous.  No matter what it is, it doesn't seem to be good.\n\nIt would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron.", progress = "I hope you found something, {name}. The Winterfall are becoming increasingly aggressive!", completion = "Disturbing news indeed. This stuff's much more like what you'd see in Felwood than in Winterspring...", objectives = "Report back to Donova Snowden with your findings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28468] = { id = 28468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "oxic Horrors", description = "I've studied the sample you returned with, and while I can't say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison.\n\nI believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors.\n\nCollect a few samples for me to compare, but be careful -- it's very dangerous there!", objectives = "Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28469] = { id = 28469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Runners", description = "Very interesting, {name}...\n\nWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.\n\nWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment.", progress = "We'll see what happens when the Winterfall don't get their firewater!", completion = "<Donova examines the contents of the crate.>\n\nI wonder if consuming this substance makes the furbolg more aggressive. They do seem much larger...", objectives = "Find and defeat the Winterfall Runner and take the Winterfall Crate from him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28470] = { id = 28470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Chief Winterfall", description = "The Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but if their leader is slain, they may not get any worse.\n\nHead east again, past where you found that cauldron. High Chief Winterfall is here, at the easternmost part of Timbermaw Post.", completion = "Thank you so much, {name}. I hope to get back to my studies without worry that I will be ambushed. Please accept this as a reward.", objectives = "Slay High Chief Winterfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28471] = { id = 28471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Piece", description = "The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them.\n\nBut perhaps Donova will be able to tell you what it says...", progress = "Now, what's this, {name}?", completion = "I wonder what all of this means... I can't make anything out...", objectives = "Bring the Crudely-written Log to Donova Snowden in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28472] = { id = 28472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of the High Chief", description = "The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper.\n\nHe's a druid that once worked to help cleanse Felwood with the Emerald Circle, and has since come here to study the nearby ruins.\n\nYou might be able to find him to the east at Lake Kel'theril, where he spends his time recently.", progress = "What is it you carry, {class}?", completion = "Yes, if you let me examine this for a while, I might be able to translate it for you.\n\n<Kelek flips through the pages.>\n\nWhen I am able to look over this fully, I will send word to you.\n\nThank you for sharing this with me, {name}. Very little is known about the Winterfall furbolg.", objectives = "Take the Crudely-written Log to Kelek Skykeeper at Lake Kel'theril.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28473] = { id = 28473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", completion = "Your actions honor your brethren and the Horde, {name}.", objectives = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths, then break them over the Black Anvil in Shadowforge City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28474] = { id = 28474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", completion = "This will not dissuade Twilight's Hammer, but perhaps it will increase the suspicion between them and the Dark Irons.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28475] = { id = 28475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", completion = "We can only hope your efforts will keep the two forces apart long enough for us to exploit their weakness.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28476] = { id = 28476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", completion = "We can only hope that the confusion and distrust you have created enables us to keep our enemies divided.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28477] = { id = 28477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", completion = "I shoulda asked you to mind control the cultists and truly tear our enemies apart. But what you did will work, {name}.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28478] = { id = 28478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", completion = "That's the way you do it when you don't have an army. And now, Twilight's Hammer won't, either.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28479] = { id = 28479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Kel'Theril", description = "At this lake, the Crystal of Zin-Malor was stolen by the Highborne. The crystal was a powerful artifact that bent arcane magic in wild and unpredictable ways... but it could only be held by the worthy, and brought doom upon all others.\n\nThe spirits that wander here span generations, each shackled here by Zin-Malor. Some will speak and tell their fates.\n\nShould you wish to learn the fate of Zin-Malor, seek the spirit at the center of the lake...", completion = "Pity me, stranger, and all the Highborne, for it was here our folly began... our folly that cursed our children, and our children's children, to this day.", objectives = "Speak with the Kaldorei Spirit at Lake Kel'theril in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28480] = { id = 28480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenants of Darkness", description = "The armies of Ramkahen are getting obliterated by Neferset's immortal guardians.\n\nThe only way to defeat them is to slay the Dark Pharaoh of Neferset.\n\nBefore we make our move, however, we're going to need to take care of his lieutenants.\n\nGo behind the battle-lines and slay Scorpion-Lord Namkhare and High Priest Sekhemet.  Only then will we be ready to confront the Dark Pharaoh himself.", completion = "You are a valuable ally, {name}.  We are one step closer to defeating the enemy.", objectives = "Slay Scorpion-Lord Namkhare and High Priest Sekhemet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28481] = { id = 28481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubled Spirits of Kel'Theril", description = "The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.\n\nIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.", objectives = "Use Gormir's Pick to find the four Highborne Relic Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28482] = { id = 28482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sullah's Gift", description = "Jonesy tells me you two need to make it up that mountain.\n\nWell, you're not going far with those troopers crawling all over it like ants on a carcass.\n\nSome of my friends were able to confiscate a bit of the enemy's hardware. It should make your journey a bit easier.\n\nMake your way up the ridgeline to the north, and you'll find it waiting for you.\n\nGood luck, you two!", completion = "Glad you could make it, {name}!", objectives = "Speak to Harrison Jones at Pilgrim's Precipice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28483] = { id = 28483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding the Enemy", description = "I will not lie to you, {name}.  We face a tremendous challenge ahead of us.\n\nAs you go behind the enemy lines into Neferset City, I want you to bring back the insignia of any Neferset scum you defeat.\n\nIt will be a boon to our armies to know that you've dealt a crushing blow to the enemy.", progress = "It is good to see you once more, {name}.", completion = "Excellent job, {name}.  Our troops will hear of your deeds.", objectives = "Obtain 10 Neferset Insignia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28484] = { id = 28484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Matter", description = "The magus has been idle for far too long and an idle magus often leads to poorly thought out schemes. This time I am charged with collecting various beast organs in order to power some type of control rod. I am far too frail to go out hunting beasts - especially yetis!\n\nPerhaps if I were to offer you a reward of some kind you would do it? All I need is for you to head west to the yeti caves and kill yetis. Rip their still beating hearts from their chests and bring them back here.", progress = "Bring me yeti hearts, {name}.", completion = "I... um... well... turns out he doesn't need the hearts anymore. Sorry about that! Hope it wasn't too inconvenient! A deal's a deal though, so here is your reward. You can go ahead and keep the yeti hearts. I hear they hold excellent nutritional value - if you're into eating.", objectives = "Collect 12 Beating Yeti Hearts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28485] = { id = 28485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetimus the Yeti Lord", description = "For years the mountain yeti of this region have been allowed free reign. Our complacency in dealing with the yeti menace has resulted in an aberration! Yetimus, lord of all yetis, has grown to a size and strength that our guard simply cannot handle. We fear that should his appetite lead him near Tarren Mill he would devour us all.\n\nGather a party of suitable adventurers and dispatch the beast. He roams the countryside to the west.\n\nBring me one of his horns and I will reward you handsomely.", progress = "Yetimus must die!", completion = "So it's true, you did kill the beast! The people of Hillsbrad are indebted to you, {name}. You have made the land safer for our citizens.\n\nTake whatever you may desire from our coffers.", objectives = "Take Yetimus' Twisted Horn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28486] = { id = 28486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet's Gambit", description = "Neferset City is too well defended.  The mountain next to it, however, is not.\n\nI've spoken to the ranger captain and he's willing to take a handful of his men and secure the strategic mountaintop.\n\nThere is one catch, {name}.  He agreed, but only if you would spearhead the attack with them.\n\nIt must be a small group, else we'll draw the enemy's attention too soon, but trust me... the rangers of Ramkahen are as tough as they come.  With you by their side we'll surely succeed.", progress = "Hail, {name}!", completion = "You did it, {name}!  Excellent!", objectives = "Escort the Ramkahen Ranger Captain to higher ground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28487] = { id = 28487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humbert's Personal Problems", description = "So this is pretty embarrassing. Where to begin?\n\nWell, you see, Melisara sent me to investigate the yeti menace in the nearby caves, west of here. It was getting late and my armor was weighing heavily on me. I took my gear off and decided to take a stroll. Yes, I, erm, went for a walk. Anyway, when I returned I discovered that my gear had been stolen! It was the yetis. I'm sure of it. They took my pants, sword and helm and ran off into their cave. Get them back for me and I will reward you.", progress = "I'm practically naked here, {name}. Help me out, eh?", completion = "Thank you, {name}! I promise you that this is the last time I take this gear off.", objectives = "Recover Humbert's Sword, Humbert's Helm, and Humbert's Pants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
